window.__texto({"id": "732158661", "paragrafos": [{"c": "identifica", "t": "PORTARIA MAPA Nº 951, DE 14 DE SETEMBRO DE 2026"}, {"c": "ementa", "t": "Institui a Rede de Acesso à Informação do Ministério da Agricultura e Pecuária e estabelece os procedimentos para tratamento dos pedidos de acesso à informação."}, {"c": "dou-paragraph", "t": "O MINISTRO DE ESTADO DA AGRICULTURA E PECUÁRIA SUBSTITUTO, no uso da atribuição que lhe confere o art. 87, parágrafo único, inciso II, da Constituição, com base no inciso III do art. 1º do Decreto nº 8.851, de 20 de setembro de 2016, e tendo em vista o disposto na Lei nº 12.527, de 18 de novembro de 2011, no Decreto nº 7.724, de 16 de maio de 2012, no Decreto nº 8.777, de 11 de maio de 2016, no Decreto nº 11.529, de 16 de maio de 2023, no Decreto nº 12.642, de 1º de outubro de 2025, e o que consta do Processo nº 21000.051238/2026-11, resolve:"}, {"c": "dou-paragraph", "t": "CAPÍTULO I"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES PRELIMINARES"}, {"c": "dou-paragraph", "t": "Art. 1º Fica instituída a Rede de Acesso à Informação do Ministério da Agricultura e Pecuária - Rede SIC/MAPA e estabelecidos os procedimentos para tratamento dos pedidos de acesso à informação."}, {"c": "dou-paragraph", "t": "Art. 2º As disposições desta Portaria aplicam-se às unidades integrantes da Rede SIC/MAPA e aos agentes públicos, aos empregados públicos, aos colaboradores e às demais pessoas que, em razão de vínculo de qualquer natureza ou do exercício de atribuições junto ao Ministério da Agricultura e Pecuária, tenham acesso, guarda ou conhecimento de informações sob custódia deste Ministério."}, {"c": "dou-paragraph", "t": "CAPÍTULO II"}, {"c": "dou-paragraph", "t": "DA REDE SIC/MAPA"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Dos objetivos"}, {"c": "dou-paragraph", "t": "Art. 3º A Rede SIC/MAPA tem por objetivos:"}, {"c": "dou-paragraph", "t": "I - fortalecer a implementação da política de acesso à informação, no âmbito do Ministério da Agricultura e Pecuária, observando os princípios básicos da administração pública e as seguintes diretrizes dispostas no art. 3º da Lei nº 12.527, de 18 de novembro de 2011:"}, {"c": "dou-paragraph", "t": "a) observância da publicidade como preceito geral e do sigilo como exceção;"}, {"c": "dou-paragraph", "t": "b) divulgação de informações de interesse público, independentemente de solicitações;"}, {"c": "dou-paragraph", "t": "c) utilização de meios de comunicação viabilizados pela tecnologia da informação;"}, {"c": "dou-paragraph", "t": "d) fomento ao desenvolvimento da cultura de transparência; e"}, {"c": "dou-paragraph", "t": "e) desenvolvimento do controle social;"}, {"c": "dou-paragraph", "t": "II - estimular a transparência ativa, a abertura de dados e a divulgação de informações de interesse coletivo ou geral, observadas as hipóteses legais de sigilo e restrição de acesso;"}, {"c": "dou-paragraph", "t": "III - promover a articulação institucional entre as unidades integrantes do Ministério da Agricultura e Pecuária para o adequado cumprimento da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "IV - padronizar procedimentos, fluxos, entendimentos e orientações relacionados ao tratamento dos pedidos de acesso à informação;"}, {"c": "dou-paragraph", "t": "V - promover o compartilhamento de boas práticas, soluções e experiências entre as unidades integrantes da Rede SIC/MAPA;"}, {"c": "dou-paragraph", "t": "VI - incentivar a capacitação permanente dos agentes públicos envolvidos no tratamento dos pedidos de acesso à informação; e"}, {"c": "dou-paragraph", "t": "VII - contribuir para o cumprimento dos prazos, a qualidade das respostas e os demais indicadores relacionados à transparência e ao acesso à informação, no âmbito do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Parágrafo único. A Rede SIC/MAPA observará, ainda, as diretrizes, procedimentos complementares, entendimentos, enunciados e instruções expedidos pela Controladoria-Geral da União, a quem compete supervisionar a aplicação do disposto no art. 68 do Decreto nº 7.724, de 16 de maio de 2012, especialmente quanto ao cumprimento dos prazos e procedimentos pelos órgãos e entidades e à qualidade do serviço de acesso à informação."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Da organização e da composição"}, {"c": "dou-paragraph", "t": "Art. 4º A Rede SIC/MAPA será coordenada pela Secretaria-Executiva do Ministério da Agricultura e Pecuária, operacionalizada por intermédio da Ouvidoria do Ministério da Agricultura e Pecuária e compreenderá as seguintes unidades:"}, {"c": "dou-paragraph", "t": "I - o Serviço de Informação ao Cidadão - SIC;"}, {"c": "dou-paragraph", "t": "II - o Gabinete do Ministro;"}, {"c": "dou-paragraph", "t": "III - a Secretaria de Política Agrícola;"}, {"c": "dou-paragraph", "t": "IV - a Secretaria de Defesa Agropecuária;"}, {"c": "dou-paragraph", "t": "V - a Secretaria de Desenvolvimento Rural;"}, {"c": "dou-paragraph", "t": "VI - a Secretaria de Comércio e Relações Internacionais;"}, {"c": "dou-paragraph", "t": "VII - da Secretaria-Executiva:"}, {"c": "dou-paragraph", "t": "a) a Subsecretaria de Planejamento, Orçamento e Administração;"}, {"c": "dou-paragraph", "t": "b) a Subsecretaria de Tecnologia da Informação;"}, {"c": "dou-paragraph", "t": "c) a Subsecretaria de Gestão de Pessoas e de Gestão do Conhecimento;"}, {"c": "dou-paragraph", "t": "d) a Subsecretaria de Governança das Superintendências; e"}, {"c": "dou-paragraph", "t": "e) o Instituto Nacional de Meteorologia; e"}, {"c": "dou-paragraph", "t": "VIII - as Superintendências de Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Parágrafo único. O SIC de que trata o inciso I do caput integra a estrutura da Ouvidoria, à qual compete exercer sua coordenação e desempenhar as atribuições previstas no art. 9º da Lei nº 12.527, de 18 de novembro de 2011."}, {"c": "dou-paragraph", "t": "Art. 5º Os dirigentes das unidades que integram a Rede SIC/MAPA indicarão, no prazo de dez dias, contados da publicação desta Portaria, no mínimo, dois agentes públicos, titular e suplente, para, na qualidade de interlocutores, atuarem no tratamento dos pedidos de acesso à informação no âmbito de suas respectivas unidades."}, {"c": "dou-paragraph", "t": "§ 1º As indicações e eventuais substituições dos interlocutores de que trata o caput deverão ser encaminhadas à Ouvidoria por meio de ofício assinado pelo dirigente máximo da unidade correspondente."}, {"c": "dou-paragraph", "t": "§ 2º Observadas as necessidades da unidade, poderão ser indicados interlocutores adicionais, em número proporcional ao volume, à complexidade ou às especificidades das demandas de acesso à informação."}, {"c": "dou-paragraph", "t": "§ 3º Os indicados de que trata o caput deverão, respeitadas as especificidades dos órgãos:"}, {"c": "dou-paragraph", "t": "I - desempenhar funções que lhes possibilitem acesso ao dirigente máximo da respectiva unidade;"}, {"c": "dou-paragraph", "t": "II - possuir conhecimento a respeito da estrutura organizacional e das atribuições das áreas técnicas da unidade em que atuem;"}, {"c": "dou-paragraph", "t": "III - apresentar facilidade de comunicação e integração com as áreas técnicas da respectiva unidade; e"}, {"c": "dou-paragraph", "t": "IV - desempenhar as competências estabelecidas no art. 26."}, {"c": "dou-paragraph", "t": "CAPÍTULO III"}, {"c": "dou-paragraph", "t": "DOS PEDIDOS DE ACESSO À INFORMAÇÃO"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Do objeto dos pedidos"}, {"c": "dou-paragraph", "t": "Art. 6º Constituirá objeto de pedido de acesso à informação, formulado com fundamento na Lei nº 12.527, de 18 de novembro de 2011, a solicitação de documentos ou dados, processados ou não, que possam ser utilizados para produção e transmissão de conhecimento, contidos em qualquer meio, suporte ou formato, produzidos ou acumulados pelo Ministério da Agricultura e Pecuária, compreendendo, ainda:"}, {"c": "dou-paragraph", "t": "I - orientação sobre os procedimentos para a consecução de acesso, bem como sobre o local onde poderá ser encontrada ou obtida a informação;"}, {"c": "dou-paragraph", "t": "II - informação contida em registros ou documentos, produzidos ou acumulados, recolhidos ou não a arquivos públicos;"}, {"c": "dou-paragraph", "t": "III - informação produzida ou custodiada por pessoa física ou entidade privada decorrente de qualquer vínculo com o Ministério da Agricultura e Pecuária, mesmo que esse vínculo já tenha cessado;"}, {"c": "dou-paragraph", "t": "IV - informação primária, íntegra, autêntica e atualizada;"}, {"c": "dou-paragraph", "t": "V - informação sobre atividades exercidas, inclusive as relativas à sua política, organização e serviços;"}, {"c": "dou-paragraph", "t": "VI - informação pertinente à administração do patrimônio do órgão, utilização de recursos públicos, licitações e contratos administrativos; e"}, {"c": "dou-paragraph", "t": "VII - informação relativa:"}, {"c": "dou-paragraph", "t": "a) à implementação, ao acompanhamento e aos resultados dos programas, projetos e ações, bem como de metas e indicadores propostos; e"}, {"c": "dou-paragraph", "t": "b) ao resultado de inspeções, auditorias, prestações e tomadas de contas realizadas pelos órgãos de controle interno e externo, incluindo prestações de contas relativas a exercícios anteriores."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Dos requisitos do pedido"}, {"c": "dou-paragraph", "t": "Art. 7º O pedido de acesso à informação, nos termos do art. 12 do Decreto nº 7.724, de 16 de maio de 2012, deverá conter:"}, {"c": "dou-paragraph", "t": "I - nome do requerente;"}, {"c": "dou-paragraph", "t": "II - número de documento de identificação válido;"}, {"c": "dou-paragraph", "t": "III - especificação, de forma clara e precisa, da informação requerida; e"}, {"c": "dou-paragraph", "t": "IV - endereço físico ou eletrônico do requerente, para recebimento de comunicações ou da informação requerida."}, {"c": "dou-paragraph", "t": "§ 1º Será facultado ao requerente de acesso à informação, devidamente identificado no sistema eletrônico disponibilizado pela Controladoria-Geral da União para o registro e o atendimento aos pedidos de acesso à informação, optar pela preservação de sua identidade."}, {"c": "dou-paragraph", "t": "§ 2º É vedada qualquer exigência relativa aos motivos determinantes do pedido de acesso à informação."}, {"c": "dou-paragraph", "t": "§ 3º A identificação do requerente não poderá conter exigências que inviabilizem o exercício do direito de acesso à informação."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Do recebimento e da tramitação dos pedidos de acesso"}, {"c": "dou-paragraph", "t": "Art. 8º Os pedidos de acesso à informação serão recebidos:"}, {"c": "dou-paragraph", "t": "I - preferencialmente, por meio do sistema de acesso à informação fornecido pela Controladoria-Geral da União;"}, {"c": "dou-paragraph", "t": "II - por correspondência eletrônica, por meio do e-mail sic.mapa@agro.gov.br;"}, {"c": "dou-paragraph", "t": "III - por correspondência física, que deverá ser dirigida ao Ministério da Agricultura e Pecuária, por meio do endereço Esplanada dos Ministérios, Bloco D, Edifício-Sede, CEP 70043-900, Brasília/DF; e"}, {"c": "dou-paragraph", "t": "IV - presencialmente, nas dependências do SIC, na Esplanada dos Ministérios, Bloco D, Edifício-Sede, Brasília/DF."}, {"c": "dou-paragraph", "t": "§ 1º Os pedidos de acesso à informação recebidos por qualquer outra unidade do Ministério da Agricultura e Pecuária deverão, na data de seu recebimento, ser encaminhados ao SIC para registro no sistema de acesso à informação, nos termos do art. 11-A, § 2º, do Decreto nº 7.724, de 16 de maio de 2012, da seguinte forma:"}, {"c": "dou-paragraph", "t": "I - os pedidos de acesso à informação recebidos por meio de e-mails institucionais deverão ser encaminhados ao SIC, por intermédio do endereço eletrônico sic.mapa@agro.gov.br;"}, {"c": "dou-paragraph", "t": "II - os pedidos recebidos por meio do Sistema Eletrônico de Informações - SEI deverão ser encaminhados à unidade do SIC, mediante despacho de encaminhamento; e"}, {"c": "dou-paragraph", "t": "III - os pedidos recebidos por meio de correspondência física deverão ser digitalizados e autuados no SEI, para posterior encaminhamento ao SIC, na forma do inciso II."}, {"c": "dou-paragraph", "t": "§ 2º O SIC disponibilizará atendimento telefônico, por meio dos contatos divulgados no sítio eletrônico do Ministério da Agricultura e Pecuária, com a finalidade de orientar o cidadão quanto à utilização do sistema eletrônico disponibilizado pela Controladoria-Geral da União e fornecer informações disponibilizadas em transparência ativa."}, {"c": "dou-paragraph", "t": "Art. 9º O SEI será utilizado para a tramitação, organização e acompanhamento dos fluxos internos relacionados ao tratamento dos pedidos de acesso e recursos, no âmbito do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "CAPÍTULO IV"}, {"c": "dou-paragraph", "t": "DO FORNECIMENTO DAS INFORMAÇÕES"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Do fornecimento e da disponibilização da informação"}, {"c": "dou-paragraph", "t": "Art. 10. O fornecimento de informação será gratuito, salvo quando o serviço de busca e fornecimento exigir a reprodução de documentos."}, {"c": "dou-paragraph", "t": "§ 1º Quando o fornecimento da informação implicar a reprodução de documentos, serão disponibilizadas gratuitamente até dez páginas e, acima desse limite, será emitida Guia de Recolhimento da União ou documento equivalente, considerando o número total de cópias para fins de ressarcimento dos custos dos serviços e dos materiais utilizados."}, {"c": "dou-paragraph", "t": "§ 2º A comprovação do pagamento da Guia de Recolhimento da União deverá ser encaminhada ao SIC, em até dez dias, por meio de correio eletrônico, correspondência física ou entrega presencial, contados da data de recebimento da resposta do SIC com as orientações para pagamento."}, {"c": "dou-paragraph", "t": "§ 3º A unidade administrativa responsável providenciará e encaminhará a informação ao SIC, no prazo de até dez dias, contados da data de recebimento da comprovação do pagamento da Guia de Recolhimento da União, para entrega ao requerente."}, {"c": "dou-paragraph", "t": "§ 4º Estará isento de ressarcir os custos previstos no § 1º aquele cuja situação econômica não lhe permita fazê-lo sem prejuízo do próprio sustento ou do sustento da família, mediante declaração, nos termos da Lei nº 7.115, de 29 de agosto de 1983."}, {"c": "dou-paragraph", "t": "Art. 11. O acesso à informação disponível deverá ser concedido imediatamente, sempre que possível."}, {"c": "dou-paragraph", "t": "§ 1º Não sendo possível o acesso imediato, a resposta deverá ser apresentada no prazo legal, observado o disposto nos arts. 38 a 42."}, {"c": "dou-paragraph", "t": "§ 2º Quando a informação solicitada estiver disponível em transparência ativa ou em outro meio de acesso universal, a resposta deverá orientar o requerente quanto ao local e à forma para sua consulta, obtenção ou reprodução, acompanhada de passo a passo que explique claramente como localizar a informação demandada."}, {"c": "dou-paragraph", "t": "§ 3º O encaminhamento das orientações de que trata o § 2º desobriga o fornecimento direto da informação, salvo quando o requerente declarar não dispor de meios para acessá-la."}, {"c": "dou-paragraph", "t": "Art. 12. Quando o volume de informações não for suportado pelo sistema de acesso à informação, estas poderão ser encaminhadas por outros meios, desde que seja devidamente informado ao requerente."}, {"c": "dou-paragraph", "t": "Parágrafo único. Na hipótese prevista no caput, a informação poderá ser disponibilizada por meio de serviço de armazenamento em nuvem, acompanhada de orientações para acesso e do prazo para realização do download, mediante entrega na sede do SIC ou por correspondência eletrônica, quando o requerente estiver identificado."}, {"c": "dou-paragraph", "t": "Art. 13. Os pedidos de acesso à informação submetidos ao Ministério da Agricultura e Pecuária não serão atendidos quando forem:"}, {"c": "dou-paragraph", "t": "I - genéricos: pedidos inespecíficos que não descrevam de forma delimitada o objeto da solicitação;"}, {"c": "dou-paragraph", "t": "II - desproporcionais: pedidos que comprometam significativamente a realização das atividades regulares das unidades do Ministério, acarretando prejuízo injustificado aos direitos de outros solicitantes;"}, {"c": "dou-paragraph", "t": "III - desarrazoados: pedidos não amparados pela Lei nº 12.527, de 18 de novembro de 2011, ou pelas garantias fundamentais previstas na Constituição Federal ou, ainda, contrários aos interesses públicos e aos princípios da segurança pública, celeridade e economicidade da Administração Pública;"}, {"c": "dou-paragraph", "t": "IV - incompreensíveis: o teor do pedido não permite compreender qual a informação desejada, impossibilitando o atendimento;"}, {"c": "dou-paragraph", "t": "V - duplicados ou repetidos: o mesmo pedido cadastrado mais de uma vez, com mesmo solicitante e teor idêntico;"}, {"c": "dou-paragraph", "t": "VI - exigir trabalhos adicionais de análise, interpretação ou consolidação de dados e informações, tais como:"}, {"c": "dou-paragraph", "t": "a) orientação sobre a aplicação de legislações ou sobre a interpretação de determinado dispositivo legal; ou"}, {"c": "dou-paragraph", "t": "b) pesquisas estruturadas que demandem a produção ou a consolidação de informações;"}, {"c": "dou-paragraph", "t": "VII - não relacionados às competências do Ministério;"}, {"c": "dou-paragraph", "t": "VIII - relacionados à prestação de serviços do Ministério, quando houver canal específico e efetivo para essa finalidade;"}, {"c": "dou-paragraph", "t": "IX - solicitar providências administrativas;"}, {"c": "dou-paragraph", "t": "X - demandar posicionamento ou manifestação das unidades do Ministério;"}, {"c": "dou-paragraph", "t": "XI - caracterizados como reclamações, solicitações de providências, denúncias e sugestões; e"}, {"c": "dou-paragraph", "t": "XII - requerimentos ou solicitações formulados por servidor público do Ministério relativos à sua situação funcional, quando houver canal específico para atendimento, hipótese em que o interessado deverá dirigir sua solicitação à unidade de gestão de pessoas à qual esteja vinculado."}, {"c": "dou-paragraph", "t": "Art. 14. As negativas de acesso à informação deverão, quando se tratar de pedido considerado:"}, {"c": "dou-paragraph", "t": "I - genérico, demonstrar que a solicitação não possui elementos básicos para a definição precisa de seu objeto;"}, {"c": "dou-paragraph", "t": "II - desproporcional, demonstrar as razões da recusa total ou parcial da demanda, apresentando os impactos negativos nas demais atividades do órgão;"}, {"c": "dou-paragraph", "t": "III - desarrazoado, ser fundamentadas quanto à desconformidade com o interesse público, a segurança pública, a celeridade ou a economicidade da Administração Pública;"}, {"c": "dou-paragraph", "t": "IV - de trabalho adicional de análise, interpretação ou consolidação de dados e informações, sempre que possível, indicar o local onde se encontram as informações necessárias para que o próprio requerente realize a interpretação, consolidação ou tratamento dos dados; e"}, {"c": "dou-paragraph", "t": "V - que não seja de competência do Ministério da Agricultura e Pecuária, indicar, sempre que possível, o órgão ou entidade competente para o fornecimento da informação."}, {"c": "dou-paragraph", "t": "Parágrafo único. O direito de acesso aos documentos ou às informações neles contidas utilizados como fundamento da tomada de decisão e do ato administrativo será assegurado com a edição do ato decisório respectivo."}, {"c": "dou-paragraph", "t": "Art. 15. Quando o acesso à informação for negado em razão de classificação de sigilo, a resposta ao requerente deverá conter os fundamentos da negativa, a indicação da autoridade classificadora responsável pela decisão e a informação acerca da possibilidade de apresentação de pedido de desclassificação da informação, nos termos da legislação vigente."}, {"c": "dou-paragraph", "t": "Parágrafo único. Na hipótese prevista no caput, deverá ser informado ao requerente o procedimento para apresentação do pedido de desclassificação, bem como a autoridade competente para sua apreciação, observado o disposto no art. 19, caput, inciso III, do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "Art. 16. Quando se tratar de acesso à informação contida em documento cuja manipulação possa prejudicar sua integridade, deverá ser oferecida a consulta de cópia, com certificação de que esta confere com o original."}, {"c": "dou-paragraph", "t": "Parágrafo único. Na impossibilidade de obtenção de cópia, o interessado poderá solicitar que a reprodução seja realizada por outro meio, às suas expensas e sob supervisão de servidor público, desde que não comprometa a conservação do documento original."}, {"c": "dou-paragraph", "t": "Art. 17. No ato da entrega da informação, o SIC deverá informar ao requerente sobre a possibilidade de interposição de recurso."}, {"c": "dou-paragraph", "t": "Parágrafo único. Caso o cidadão tenha interesse em interpor recurso após a disponibilização da informação, deverá ser informado pelo SIC de que poderá fazê-lo no prazo de dez dias, contado da data de entrega da informação."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Das informações pessoais"}, {"c": "dou-paragraph", "t": "Art. 18. O tratamento, o acesso, a restrição de acesso e a proteção das informações pessoais, no âmbito do Ministério da Agricultura e Pecuária, observarão o disposto no art. 31 da Lei nº 12.527, de 18 de novembro de 2011, e nos arts. 55 a 62 do Decreto nº 7.724, de 16 de maio de 2012, sem prejuízo dos procedimentos específicos estabelecidos nesta Portaria."}, {"c": "dou-paragraph", "t": "Art. 19. O pedido de acesso a informações pessoais formulado pelo próprio titular observará os procedimentos previstos nesta Portaria e estará condicionado à comprovação de sua identidade, nos termos do art. 60 do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "§ 1º Considera-se comprovada a identidade do requerente quando o pedido for apresentado por meio do sistema de acesso à informação mediante autenticação em conta Gov.br com nível de confiabilidade Prata ou Ouro."}, {"c": "dou-paragraph", "t": "§ 2º Quando a autenticação não ocorrer na forma prevista no § 1º, o SIC poderá solicitar documentação complementar ou adotar outros procedimentos idôneos destinados à confirmação da identidade do requerente, previamente ao fornecimento da informação."}, {"c": "dou-paragraph", "t": "§ 3º Comprovada a identidade do requerente, as informações pessoais poderão ser disponibilizadas por meio eletrônico, desde que adotadas medidas aptas a preservar sua confidencialidade e integridade."}, {"c": "dou-paragraph", "t": "§ 4º O pedido de acesso a informações pessoais formulado por terceiro observará o disposto no art. 61 do Decreto nº 7.724, de 16 de maio de 2012, e deverá estar acompanhado da documentação comprobatória pertinente à hipótese legal invocada."}, {"c": "dou-paragraph", "t": "§ 5º A procuração encaminhada por meio do sistema de acesso à informação poderá ser aceita quando sua autenticidade puder ser verificada pelos meios disponíveis à Administração."}, {"c": "dou-paragraph", "t": "Art. 20. O acesso a informações pessoais por terceiros será condicionado à assinatura de termo de responsabilidade, conforme modelo constante do Anexo, que disporá sobre a finalidade e a destinação que fundamentaram a autorização de acesso, bem como sobre as obrigações assumidas pelo requerente."}, {"c": "dou-paragraph", "t": "§ 1º A utilização das informações pessoais ficará vinculada à finalidade que fundamentou a autorização de acesso, vedada sua utilização para finalidade diversa."}, {"c": "dou-paragraph", "t": "§ 2º A utilização indevida das informações pessoais sujeitará o responsável às sanções previstas na legislação aplicável."}, {"c": "dou-paragraph", "t": "Art. 21. A existência de informações pessoais em documentos, processos ou bases de dados não constituirá, por si só, fundamento para a negativa integral de acesso à informação."}, {"c": "dou-paragraph", "t": "Parágrafo único. Sempre que possível, deverão ser adotadas medidas de tratamento da informação, inclusive mediante ocultação, anonimização, pseudonimização, tarjamento, exclusão ou descaracterização de dados pessoais, de modo a viabilizar o acesso à parcela da informação não sujeita à restrição de acesso."}, {"c": "dou-paragraph", "t": "CAPÍTULO V"}, {"c": "dou-paragraph", "t": "DOS AGENTES, DAS COMPETÊNCIAS E DO TRATAMENTO"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Dos agentes responsáveis"}, {"c": "dou-paragraph", "t": "Art. 22. Os agentes públicos responsáveis pelo tratamento dos pedidos de acesso à informação serão identificados de acordo com os seguintes perfis:"}, {"c": "dou-paragraph", "t": "I - representante do SIC: servidor responsável pelo SIC;"}, {"c": "dou-paragraph", "t": "II - interlocutor: agente público designado pelo dirigente máximo da unidade para atuar no tratamento dos pedidos de acesso à informação, no âmbito de sua unidade; e"}, {"c": "dou-paragraph", "t": "III - responsável técnico: agente público responsável pela validação, assinatura e encaminhamento das respostas aos pedidos de acesso à informação, no âmbito de sua unidade, observada a seguinte estrutura de cargos:"}, {"c": "dou-paragraph", "t": "a) nos órgãos de assistência direta e imediata ao Ministro:"}, {"c": "dou-paragraph", "t": "1. o Coordenador-Geral do Gabinete, no Gabinete;"}, {"c": "dou-paragraph", "t": "2. os Chefes de Assessoria, nas respectivas Assessorias;"}, {"c": "dou-paragraph", "t": "3. o Ouvidor, na Ouvidoria;"}, {"c": "dou-paragraph", "t": "4. o Corregedor, na Corregedoria; e"}, {"c": "dou-paragraph", "t": "5. o Consultor Jurídico, na Consultoria Jurídica;"}, {"c": "dou-paragraph", "t": "6. os Subsecretários, nas respectivas Subsecretarias da Secretaria-Executiva;"}, {"c": "dou-paragraph", "t": "7. o Diretor, no Instituto Nacional de Meteorologia da Secretaria-Executiva;"}, {"c": "dou-paragraph", "t": "b) nas Secretarias de que tratam os incisos III a VII do caput do art. 4º, os respectivos Diretores; e"}, {"c": "dou-paragraph", "t": "c) nas Superintendências de Agricultura e Pecuária, os respectivos Superintendentes."}, {"c": "dou-paragraph", "t": "Parágrafo único. O servidor de que trata o inciso I do caput atuará em conformidade com as atribuições previstas no art. 9º da Lei nº 12.527, de 18 de novembro de 2011, e com as competências estabelecidas no art. 25."}, {"c": "dou-paragraph", "t": "Art. 23. As autoridades hierárquicas responsáveis pelas decisões dos recursos em primeira instância, de que trata o art. 15 da Lei nº 12.527, de 18 de novembro de 2011, serão identificadas de acordo com os seguintes cargos:"}, {"c": "dou-paragraph", "t": "I - o Chefe de Gabinete do Ministro, quando se tratar de recursos apresentados no âmbito dos seguintes órgãos:"}, {"c": "dou-paragraph", "t": "a) Coordenação-Geral do Gabinete;"}, {"c": "dou-paragraph", "t": "b) Assessorias;"}, {"c": "dou-paragraph", "t": "c) Ouvidoria;"}, {"c": "dou-paragraph", "t": "d) Corregedoria; e"}, {"c": "dou-paragraph", "t": "e) Consultoria Jurídica;"}, {"c": "dou-paragraph", "t": "II - o Secretário-Executivo, quando se tratar de recursos apresentados no âmbito das Subsecretarias, do Instituto Nacional de Meteorologia e na hipótese prevista no art. 31, parágrafo único;"}, {"c": "dou-paragraph", "t": "III - os Secretários, quando se tratar de recursos apresentados no âmbito dos Departamentos de suas respectivas Secretarias; e"}, {"c": "dou-paragraph", "t": "IV - o Subsecretário de Gestão das Superintendências ou cargo equivalente, quando se tratar de recursos apresentados no âmbito das Superintendências de Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 1º Quando a resposta ao pedido de acesso à informação for elaborada diretamente pelo SIC, o recurso em primeira instância será decidido pelo Ouvidor."}, {"c": "dou-paragraph", "t": "§ 2º Quando a resposta fornecida diretamente pelo SIC for fundamentada em manifestação previamente homologada pela unidade competente ou quando a informação solicitada estiver disponível em transparência ativa, o recurso em primeira instância será submetido à autoridade hierárquica da unidade responsável pela informação para decisão."}, {"c": "dou-paragraph", "t": "Art. 24. Os recursos negados em primeira instância serão apreciados, em segunda instância, pelo Ministro de Estado da Agricultura e Pecuária ou por seu substituto legal."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Das competências e do tratamento"}, {"c": "dou-paragraph", "t": "Subseção I"}, {"c": "dou-paragraph", "t": "Do representante do SIC"}, {"c": "dou-paragraph", "t": "Art. 25. Compete ao representante do SIC de que trata o inciso I do art. 22 assegurar o atendimento aos pedidos de acesso à informação e aos recursos apresentados ao Ministério da Agricultura e Pecuária, mediante as seguintes atribuições:"}, {"c": "dou-paragraph", "t": "I - receber e realizar análise prévia dos pedidos de acesso à informação e dos recursos;"}, {"c": "dou-paragraph", "t": "II - promover o encaminhamento do requerimento ao órgão ou entidade competente, por meio do sistema de acesso à informação, quando não se tratar de matéria de competência do Ministério e o destinatário possuir cadastro ativo na plataforma;"}, {"c": "dou-paragraph", "t": "III - verificar a existência de informação disponível em transparência ativa, de precedentes publicados pela Controladoria-Geral da União ou de resposta previamente homologada pela unidade competente, que permita o atendimento direto do requerimento pelo SIC;"}, {"c": "dou-paragraph", "t": "IV - encaminhar o pedido ao interlocutor da unidade competente, mediante formulário de encaminhamento no SEI, quando não houver informação disponível ou quando não for possível atestar sua adequação ao caso concreto;"}, {"c": "dou-paragraph", "t": "V - comunicar ao requerente a necessidade de dilação de prazo para a resposta, quando cabível;"}, {"c": "dou-paragraph", "t": "VI - registrar, no sistema de acesso à informação, a resposta recebida para encaminhamento ao requerente, identificando a unidade responsável pela sua elaboração;"}, {"c": "dou-paragraph", "t": "VII - informar ao requerente sobre o direito de interpor recurso nos casos de negativa de acesso à informação ou de ausência de apresentação das razões da negativa;"}, {"c": "dou-paragraph", "t": "VIII - orientar que as respostas sejam redigidas em linguagem simples, clara e acessível, evitando o uso de jargões ou termos técnicos desnecessários;"}, {"c": "dou-paragraph", "t": "IX - propor às unidades a inclusão, no sítio eletrônico do Ministério, de informações frequentemente solicitadas pelos cidadãos, com vistas ao fortalecimento da transparência ativa;"}, {"c": "dou-paragraph", "t": "X - fomentar, junto às unidades competentes, a elaboração, homologação e atualização de respostas padrão para atendimento de pedidos recorrentes de acesso à informação;"}, {"c": "dou-paragraph", "t": "XI - propor ações destinadas ao aprimoramento da qualidade e à uniformização dos procedimentos internos junto aos demais integrantes da Rede SIC/MAPA;"}, {"c": "dou-paragraph", "t": "XII - elaborar relatório anual de que trata o art. 45 do Decreto nº 7.724, de 16 de maio de 2012;"}, {"c": "dou-paragraph", "t": "XIII - atuar em coordenação com a Comissão Permanente de Avaliação de Documentos Sigilosos - CPADS/MAPA e com as instâncias do Sistema de Integridade, Transparência e Acesso à Informação da Administração Pública Federal - Sitai, observadas as diretrizes da Controladoria-Geral da União; e"}, {"c": "dou-paragraph", "t": "XIV - encaminhar os casos de omissões e as reclamações à Autoridade de Monitoramento para conhecimento e providências cabíveis, de acordo com o disposto no art. 67, caput, inciso V, do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "§ 1º Quando o pedido envolver matéria de competência de mais de uma unidade, o requerimento será encaminhado a todas as unidades responsáveis pela prestação das informações e o SIC ficará responsável pela consolidação das respostas."}, {"c": "dou-paragraph", "t": "§ 2º O SIC submeterá à apreciação da Secretaria-Executiva os pedidos de acesso à informação que envolvam matéria de relevante repercussão institucional ou demandem alinhamento entre as manifestações de duas ou mais unidades administrativas."}, {"c": "dou-paragraph", "t": "§ 3º Na hipótese prevista no inciso II do caput, quando o órgão ou entidade competente não possuir cadastro ativo no sistema de acesso à informação, o SIC concluirá o pedido, indicando ao requerente, sempre que possível, o órgão ou entidade que detém a informação solicitada."}, {"c": "dou-paragraph", "t": "§ 4º Para os efeitos do inciso III do caput, quando a informação disponível demandar validação quanto à sua confiabilidade, integridade ou autenticidade, o SIC deverá encaminhar o pedido ao interlocutor da unidade competente, estabelecendo prazo para manifestação."}, {"c": "dou-paragraph", "t": "§ 5º Na hipótese de necessidade de retificação ou complementação da resposta, o SIC encaminhará a solicitação ao interlocutor da unidade competente, com a indicação dos ajustes necessários."}, {"c": "dou-paragraph", "t": "Subseção II"}, {"c": "dou-paragraph", "t": "Dos interlocutores"}, {"c": "dou-paragraph", "t": "Art. 26. Compete ao interlocutor:"}, {"c": "dou-paragraph", "t": "I - receber e analisar os pedidos de acesso à informação submetidos pelo SIC e encaminhá-los ao responsável técnico, conforme qualificados no art. 22, caput, inciso III, para elaboração de resposta;"}, {"c": "dou-paragraph", "t": "II - devolver imediatamente o pedido ao SIC quando a informação não estiver sob a competência de sua unidade, fornecendo, sempre que possível, informações sobre a área, o órgão ou a entidade competente;"}, {"c": "dou-paragraph", "t": "III - manter canais de comunicação com as demais instâncias de sua esfera de atuação e, quando necessário, com outras unidades relacionadas à informação solicitada, com vistas ao adequado encaminhamento e tratamento dos pedidos de acesso à informação;"}, {"c": "dou-paragraph", "t": "IV - analisar a resposta elaborada pelo responsável técnico e, quando necessário, orientá-lo quanto à qualidade da resposta e à necessidade de fundamentação da negativa de acesso à informação;"}, {"c": "dou-paragraph", "t": "V - verificar o adequado tratamento das informações pessoais, sigilosas ou sujeitas a restrição de acesso e orientar o responsável técnico quanto às medidas necessárias à proteção dessas informações antes do encaminhamento da resposta ao SIC;"}, {"c": "dou-paragraph", "t": "VI - verificar se a resposta ao pedido de acesso à informação foi devidamente assinada pelo responsável técnico e, quando necessário, devolvê-la para ajuste;"}, {"c": "dou-paragraph", "t": "VII - encaminhar ao SIC, mediante despacho, a resposta elaborada pelo responsável técnico, observados os trâmites aplicáveis;"}, {"c": "dou-paragraph", "t": "VIII - receber os recursos e proceder ao seu encaminhamento conforme as autoridades hierárquicas definidas no art. 23; e"}, {"c": "dou-paragraph", "t": "IX - observar o cumprimento dos prazos previstos nos arts. 38 a 42."}, {"c": "dou-paragraph", "t": "Subseção III"}, {"c": "dou-paragraph", "t": "Dos responsáveis técnicos"}, {"c": "dou-paragraph", "t": "Art. 27. Compete ao responsável técnico as seguintes atribuições:"}, {"c": "dou-paragraph", "t": "I - verificar se a informação solicitada se encontra disponível em transparência ativa e, quando for o caso, indicar ao requerente o local e a forma de acesso, inclusive por meio de link eletrônico e de orientações claras para sua localização, de modo a possibilitar o atendimento imediato do pedido;"}, {"c": "dou-paragraph", "t": "II - verificar a existência de precedentes relacionados a pedidos de acesso à informação sobre matéria semelhante, com vistas a assegurar a uniformidade de entendimento e a consistência das respostas;"}, {"c": "dou-paragraph", "t": "III - assegurar que as respostas aos pedidos de acesso à informação sob sua responsabilidade sejam redigidas de forma clara, objetiva, simples e de fácil compreensão, evitando o uso desnecessário de siglas, termos técnicos ou estrangeirismos, observado o disposto no art. 5º da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "IV - formalizar ao interlocutor de sua unidade a necessidade de dilação de prazo para o fornecimento de resposta ao cidadão, por meio da apresentação de justificativa expressa, conforme o disposto no art. 11, § 2º, da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "V - apresentar justificativa para a negativa de acesso à informação, total ou parcial, quando for o caso, com fundamento na Lei nº 12.527, de 18 de novembro de 2011, ou em outras hipóteses legais de restrição de acesso;"}, {"c": "dou-paragraph", "t": "VI - assinar e encaminhar ao interlocutor as respostas aos pedidos de acesso à informação afetos à sua unidade, ainda que sua instrução tenha contado com subsídios fornecidos por unidades sob sua subordinação;"}, {"c": "dou-paragraph", "t": "VII - prestar informações e subsídios técnicos para a apreciação dos recursos interpostos em face das respostas aos pedidos de acesso à informação sob sua responsabilidade;"}, {"c": "dou-paragraph", "t": "VIII - avaliar e propor a inclusão, no sítio eletrônico do Ministério da Agricultura e Pecuária, de informações frequentemente solicitadas pelos cidadãos, com vistas ao fortalecimento da transparência ativa, desde que certificada sua natureza pública;"}, {"c": "dou-paragraph", "t": "IX - elaborar, homologar e atualizar, quando cabível, respostas padrão para atendimento de pedidos recorrentes de acesso à informação e submetê-las ao SIC para utilização; e"}, {"c": "dou-paragraph", "t": "X - assegurar o cumprimento dos prazos previstos nos arts. 38 a 42."}, {"c": "dou-paragraph", "t": "Subseção IV"}, {"c": "dou-paragraph", "t": "Dos dirigentes"}, {"c": "dou-paragraph", "t": "Art. 28. Compete aos dirigentes:"}, {"c": "dou-paragraph", "t": "I - analisar e decidir sobre os recursos apresentados pelo requerente em razão da negativa de acesso às informações solicitadas no âmbito de sua unidade;"}, {"c": "dou-paragraph", "t": "II - receber, analisar e adotar providências a respeito das reclamações apresentadas à Autoridade de Monitoramento de que trata o art. 47 em razão dos casos de omissão de informações no âmbito de sua unidade, conforme o previsto no art. 40 da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "III - prover subsídios que apoiem o Ministro de Estado da Agricultura e Pecuária na avaliação dos recursos interpostos em segunda instância, decorrentes de decisões que negaram o acesso à informação sob a responsabilidade da unidade;"}, {"c": "dou-paragraph", "t": "IV - fornecer esclarecimentos à Controladoria-Geral da União e à Comissão Mista de Reavaliação de Informações necessários à decisão dos recursos apresentados em terceira e quarta instâncias, respectivamente, relativos a sua unidade; e"}, {"c": "dou-paragraph", "t": "V - assegurar a conformidade das informações da unidade com as disposições da Lei nº 12.527, de 18 de novembro de 2011, bem como a observância dos prazos, a clareza nas respostas e a aderência aos procedimentos de transparência ativa."}, {"c": "dou-paragraph", "t": "Subseção V"}, {"c": "dou-paragraph", "t": "Do Ministro de Estado da Agricultura e Pecuária"}, {"c": "dou-paragraph", "t": "Art. 29. Compete ao Ministro de Estado da Agricultura e Pecuária:"}, {"c": "dou-paragraph", "t": "I - decidir sobre os recursos apresentados em grau de segunda instância, referentes à negativa de acesso à informação, no âmbito do Ministério;"}, {"c": "dou-paragraph", "t": "II - classificar as informações nos graus de sigilo ultrassecreto, secreto e reservado e exercer a competência para delegar essa atribuição, observado o disposto no art. 27 da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "III - determinar a publicação anual, no sítio eletrônico do Ministério, do rol de informações desclassificadas, do rol de documentos classificados por grau de sigilo e do relatório estatístico dos pedidos de acesso à informação, na forma do art. 30 da Lei nº 12.527, de 18 de novembro de 2011; e"}, {"c": "dou-paragraph", "t": "IV - aprovar diretrizes e normas relacionadas à Lei nº 12.527, de 18 de novembro de 2011, e apoiar medidas destinadas ao aprimoramento da transparência e do acesso à informação, no âmbito do Ministério, em consonância com a Política de Transparência e Acesso à Informação do Governo Federal."}, {"c": "dou-paragraph", "t": "CAPÍTULO VI"}, {"c": "dou-paragraph", "t": "DOS RECURSOS"}, {"c": "dou-paragraph", "t": "Art. 30. Negado o acesso à informação ou não apresentadas as razões da negativa, o requerente poderá interpor recurso, no prazo de dez dias, contados da data de recebimento da negativa, observadas as disposições da Lei nº 12.527, de 18 de novembro de 2011, e seus regulamentos."}, {"c": "dou-paragraph", "t": "Art. 31. Interposto recurso em primeira instância, o SIC realizará análise preliminar e o encaminhará ao interlocutor da unidade responsável pela resposta recorrida."}, {"c": "dou-paragraph", "t": "Parágrafo único. Quando o recurso recair sobre pedido de acesso à informação cuja resposta tenha sido elaborada por mais de uma unidade sujeita a autoridades recursais distintas, caberá ao Secretário-Executivo apreciar e decidir o recurso em primeira instância."}, {"c": "dou-paragraph", "t": "Art. 32. Interposto recurso em segunda instância, o SIC encaminhará o processo ao interlocutor da unidade competente pela resposta inicial para submissão ao dirigente responsável pelo recurso em primeira instância, bem como à Autoridade de Monitoramento, para subsidiar a decisão do Ministro da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 33. A apreciação dos recursos observará as seguintes instâncias recursais:"}, {"c": "dou-paragraph", "t": "I - instâncias recursais internas, correspondentes às autoridades responsáveis pela apreciação dos recursos em primeira e segunda instâncias, definidas nos arts. 28 e 29, observada a hierarquia recursal prevista no art. 15 da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "II - Controladoria-Geral da União; e"}, {"c": "dou-paragraph", "t": "III - Comissão Mista de Reavaliação de Informações."}, {"c": "dou-paragraph", "t": "Art. 34. As decisões proferidas em sede recursal deverão indicar, de forma clara e fundamentada, os motivos de fato e de direito que as embasam, especialmente quando mantida a negativa de acesso à informação."}, {"c": "dou-paragraph", "t": "Art. 35. Quando a decisão recursal determinar o fornecimento da informação, deverão ser adotadas as providências necessárias ao seu atendimento, observadas as disposições legais relativas à proteção de informações pessoais, sigilosas ou sujeitas a restrição de acesso."}, {"c": "dou-paragraph", "t": "Art. 36. Os recursos interpostos perante a Controladoria-Geral da União e a Comissão Mista de Reavaliação de Informações serão instruídos com as informações e manifestações necessárias à adequada apreciação da matéria, observados os procedimentos, as orientações e os prazos estabelecidos por essas instâncias."}, {"c": "dou-paragraph", "t": "CAPÍTULO VII"}, {"c": "dou-paragraph", "t": "DA OMISSÃO E DA RECLAMAÇÃO"}, {"c": "dou-paragraph", "t": "Art. 37. Considera-se omissão, para os fins da Lei nº 12.527, de 18 de novembro de 2011, e do Decreto nº 7.724, de 16 de maio de 2012, a ausência de manifestação da autoridade competente quanto ao pedido de acesso à informação, após o decurso dos prazos legalmente estabelecidos."}, {"c": "dou-paragraph", "t": "§ 1º A omissão na apreciação do pedido de acesso à informação sujeita-se ao procedimento de reclamação dirigido à Autoridade de Monitoramento da Lei nº 12.527, de 18 de novembro de 2011, nos termos do art. 22 do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "§ 2º A omissão na apreciação do recurso será tratada de acordo com as disposições recursais previstas na Lei nº 12.527, de 18 de novembro de 2011, e no Decreto nº 7.724, de 16 de maio de 2012, assegurado ao requerente o acesso às instâncias competentes para apreciação da matéria."}, {"c": "dou-paragraph", "t": "§ 3º Na hipótese de descumprimento do disposto no caput, a Autoridade de Monitoramento da Lei nº 12.527, de 18 de novembro de 2011, poderá comunicar o fato à Corregedoria do Ministério da Agricultura e Pecuária, quando houver indícios da prática de conduta passível de responsabilização, para apuração na forma da legislação aplicável."}, {"c": "dou-paragraph", "t": "CAPÍTULO VIII"}, {"c": "dou-paragraph", "t": "DOS PRAZOS"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Dos pedidos de acesso à informação"}, {"c": "dou-paragraph", "t": "Art. 38. Os pedidos de acesso à informação deverão ser respondidos no prazo de até vinte dias, contados da data de seu registro no sistema de acesso à informação."}, {"c": "dou-paragraph", "t": "Parágrafo único. O prazo previsto no caput poderá ser prorrogado, uma única vez, por até dez dias, mediante justificativa expressa do responsável técnico, da qual será cientificado o requerente antes do término do prazo inicialmente estabelecido, nos termos do art. 11, § 2º, da Lei nº 12.527, de 18 de novembro de 2011."}, {"c": "dou-paragraph", "t": "Art. 39. Para assegurar o cumprimento dos prazos legais previstos no art. 38, as unidades responsáveis pela informação deverão adotar os fluxos internos que julgarem necessários para que a resposta seja encaminhada ao SIC no prazo de até quinze dias, contados da data de recebimento do pedido."}, {"c": "dou-paragraph", "t": "Parágrafo único. O prazo previsto no caput compreenderá todas as etapas necessárias à elaboração, à análise, à revisão, à assinatura e ao encaminhamento da resposta ao SIC."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Dos recursos"}, {"c": "dou-paragraph", "t": "Art. 40. As decisões sobre os recursos interpostos em grau de primeira e segunda instância deverão ser proferidas no prazo de até cinco dias, contados da data de seu recebimento, conforme estabelecido no art. 21 do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "§ 1º Ao receber os recursos de que trata o caput, o SIC deverá preencher o formulário de encaminhamento no SEI, considerando o prazo estabelecido no sistema de acesso à informação, estipulando prazo interno para retorno da decisão."}, {"c": "dou-paragraph", "t": "§ 2º Para assegurar o cumprimento dos prazos legais previstos no caput, as unidades responsáveis pela instrução e decisão dos recursos deverão adotar os fluxos internos que julgarem necessários para que a resposta seja encaminhada ao SIC no prazo estabelecido nos formulários de encaminhamento dos recursos."}, {"c": "dou-paragraph", "t": "Art. 41. A inobservância dos prazos internos estabelecidos nos formulários de encaminhamentos dos recursos não afastará o dever de cumprimento dos prazos legais previstos na Lei nº 12.527, de 18 de novembro de 2011."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Das reclamações por omissões"}, {"c": "dou-paragraph", "t": "Art. 42. Na hipótese de omissão de resposta ao pedido de acesso à informação, o requerente poderá apresentar reclamação à Autoridade de Monitoramento da Lei nº 12.527, de 18 de novembro de 2011, no prazo de dez dias, contados da data de vencimento do prazo para resposta."}, {"c": "dou-paragraph", "t": "§ 1º A Autoridade de Monitoramento manifestar-se-á no prazo de cinco dias, contados da data de recebimento da reclamação nos termos do art. 22 do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "§ 2º Os prazos internos necessários à instrução da reclamação deverão ser definidos de modo a assegurar o cumprimento do prazo previsto no § 1º."}, {"c": "dou-paragraph", "t": "CAPÍTULO IX"}, {"c": "dou-paragraph", "t": "DAS RESPONSABILIDADES"}, {"c": "dou-paragraph", "t": "Art. 43. Os integrantes da Rede SIC/MAPA deverão observar as disposições da Lei nº 12.527, de 18 de novembro de 2011, do Decreto nº 7.724, de 16 de maio de 2012, e das demais normas aplicáveis ao acesso à informação, sujeitando-se à responsabilização pelas condutas ilícitas previstas na legislação."}, {"c": "dou-paragraph", "t": "Parágrafo único. O disposto no caput e nos arts. 44 a 46 aplica-se igualmente aos agentes públicos, empregados públicos, colaboradores e demais pessoas que, em razão de vínculo ou do exercício de atribuições junto ao Ministério da Agricultura e Pecuária, tenham acesso, guarda ou conhecimento de informações sob custódia do órgão."}, {"c": "dou-paragraph", "t": "Art. 44. Constituem condutas passíveis de responsabilização aquelas previstas no art. 32 da Lei nº 12.527, de 18 de novembro de 2011, e no art. 65 do Decreto nº 7.724, de 16 de maio de 2012, sem prejuízo das demais hipóteses de responsabilização previstas na legislação aplicável."}, {"c": "dou-paragraph", "t": "Art. 45. No caso de extravio da informação objeto de pedido de acesso, poderá o interessado requerer à autoridade competente a imediata abertura de sindicância destinada à apuração do desaparecimento da respectiva documentação, nos termos do art. 7º da Lei nº 12.527, de 18 de novembro de 2011."}, {"c": "dou-paragraph", "t": "Art. 46. A pessoa natural ou entidade privada que detenha informações em virtude de vínculo de qualquer natureza com o Ministério da Agricultura e Pecuária deverá observar as disposições aplicáveis ao acesso à informação e sujeitar-se-á às sanções previstas na legislação em caso de descumprimento."}, {"c": "dou-paragraph", "t": "§ 1º Quando a informação objeto do pedido estiver sob a guarda de pessoa natural ou entidade privada de que trata o caput, caberá à unidade competente do Ministério da Agricultura e Pecuária adotar as providências necessárias para sua obtenção, permanecendo o Ministério responsável pelo atendimento do pedido de acesso à informação."}, {"c": "dou-paragraph", "t": "§ 2º As sanções aplicáveis às pessoas naturais e às entidades privadas observarão o disposto no art. 66 do Decreto nº 7.724, de 16 de maio de 2012, e demais normas pertinentes."}, {"c": "dou-paragraph", "t": "CAPÍTULO X"}, {"c": "dou-paragraph", "t": "DO MONITORAMENTO DA LEI Nº 12.527, DE 18 DE NOVEMBRO DE 2011"}, {"c": "dou-paragraph", "t": "Art. 47. O monitoramento da aplicação da Lei nº 12.527, de 18 de novembro de 2011, compete à Autoridade de Monitoramento da Lei nº 12.527, de 18 de novembro de 2011, exercida pelo Chefe da Assessoria Especial de Controle Interno do Ministério da Agricultura e Pecuária, nos termos do art. 5º, § 1º, do Decreto nº 11.529, de 16 de maio de 2023."}, {"c": "dou-paragraph", "t": "Parágrafo único. Para o exercício das competências previstas no art. 40 da Lei nº 12.527, de 18 de novembro de 2011, e no art. 67 do Decreto nº 7.724, de 16 de maio de 2012, a Autoridade de Monitoramento acompanhará a atuação da Rede SIC/MAPA, com a finalidade de avaliar o cumprimento da Lei nº 12.527, de 18 de novembro de 2011, no âmbito do Ministério, podendo solicitar informações, indicadores e outros elementos necessários ao desempenho de suas atribuições."}, {"c": "dou-paragraph", "t": "Art. 48. No exercício das atividades de monitoramento da Rede SIC/MAPA, compete à Autoridade de Monitoramento:"}, {"c": "dou-paragraph", "t": "I - assegurar o cumprimento das normas relativas ao acesso à informação, de forma eficiente e adequada aos objetivos da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "II - elaborar relatório anual com informações referentes à implementação da Lei nº 12.527, de 18 de novembro de 2011, no âmbito do Ministério, que será encaminhado ao Ministro de Estado da Agricultura e Pecuária, conforme disposto no art. 67, caput, inciso II, do Decreto nº 7.724, de 16 de maio de 2012;"}, {"c": "dou-paragraph", "t": "III - recomendar as medidas indispensáveis à implementação e ao aperfeiçoamento das normas e dos procedimentos necessários ao correto cumprimento do disposto na Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "IV - orientar as unidades do Ministério da Agricultura e Pecuária quanto ao cumprimento das disposições da Lei nº 12.527, de 18 de novembro de 2011, e de seus regulamentos;"}, {"c": "dou-paragraph", "t": "V - manifestar-se sobre as reclamações apresentadas em razão de omissão de resposta a pedidos de acesso à informação, observadas as disposições da legislação aplicável;"}, {"c": "dou-paragraph", "t": "VI - encaminhar à Corregedoria do Ministério da Agricultura e Pecuária os casos de descumprimento da Lei nº 12.527, de 18 de novembro de 2011, para apuração de eventual infração administrativa, conforme previsto no art. 32 da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "VII - avaliar e monitorar a implementação da transparência ativa e passiva no âmbito do Ministério, bem como recomendar medidas destinadas ao seu aperfeiçoamento;"}, {"c": "dou-paragraph", "t": "VIII - solicitar informações e esclarecimentos às unidades integrantes da Rede SIC/MAPA sempre que necessários ao exercício de suas atribuições; e"}, {"c": "dou-paragraph", "t": "IX - subsidiar o Ministro de Estado da Agricultura e Pecuária na apreciação dos recursos em segunda instância interpostos com fundamento na Lei nº 12.527, de 18 de novembro de 2011."}, {"c": "dou-paragraph", "t": "Parágrafo único. As unidades integrantes da Rede SIC/MAPA deverão prestar, tempestivamente, as informações e os esclarecimentos solicitados pela Autoridade de Monitoramento, bem como adotar as providências necessárias ao atendimento das orientações e recomendações expedidas no exercício de suas atribuições."}, {"c": "dou-paragraph", "t": "CAPÍTULO XI"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES FINAIS"}, {"c": "dou-paragraph", "t": "Art. 49. As dúvidas sobre a aplicação desta Portaria e as solicitações de esclarecimentos adicionais deverão ser dirigidas à Ouvidoria, por meio do SIC, pelos canais oficiais constantes do art. 8º."}, {"c": "dou-paragraph", "t": "Art. 50. Esta Portaria será revisada periodicamente para garantir sua atualização e eficácia, levando em consideração as mudanças na legislação, as necessidades identificadas e as práticas recomendadas no campo do acesso à informação e da transparência pública."}, {"c": "dou-paragraph", "t": "Art. 51. Fica revogada a Portaria MAPA nº 147, de 23 de abril de 2020."}, {"c": "dou-paragraph", "t": "Art. 52. Esta Portaria entra em vigor trinta dias após a data de sua publicação."}, {"c": "assina", "t": "CLEBER OLIVEIRA SOARES"}, {"c": "anexo", "t": "ANEXOTERMO DE RESPONSABILIDADE PARA ACESSO À INFORMAÇÃO PESSOAL POR TERCEIROS"}, {"c": "dou-paragraph", "t": "Nos termos do disposto na Lei nº 12.527, de 18 de novembro de 2011, e de sua regulamentação, declaro que tive acesso à informação aqui descrita e que a utilizarei exclusivamente com a finalidade declarada, responsabilizando-me civil, penal e administrativamente por qualquer uso diverso ou por qualquer prejuízo à intimidade, à honra e à vida privada de seus titulares e de seus herdeiros."}, {"c": "dou-paragraph", "t": "Dados da informação:"}, {"c": "", "t": "Nome completo dos titulares da informação:"}, {"c": "", "t": "Descrição da informação:"}, {"c": "", "t": "Finalidade do acesso:"}, {"c": "", "t": "Forma do acesso:"}, {"c": "", "t": "[acesso local], [cópia]"}, {"c": "", "t": "Data do acesso:"}, {"c": "", "t": "Prazo de acesso (quando aplicável)"}, {"c": "", "t": "Entre [00:00] e [00:00] horas"}, {"c": "dou-paragraph", "t": "Dados do requerente:"}, {"c": "", "t": "Nome completo:"}, {"c": "", "t": "Endereço residencial:"}, {"c": "", "t": "Documento de identificação"}, {"c": "", "t": "[incluir a cópia do documento com foto]"}, {"c": "", "t": "Telefone:"}, {"c": "dou-paragraph", "t": "(Local), (data)"}, {"c": "dou-paragraph", "t": "_________________________________________"}, {"c": "dou-paragraph", "t": "(Assinatura do requerente)"}, {"c": "identifica", "t": "PORTARIA MAPA Nº 951, DE 14 DE SETEMBRO DE 2026"}, {"c": "ementa", "t": "Institui a Rede de Acesso à Informação do Ministério da Agricultura e Pecuária e estabelece os procedimentos para tratamento dos pedidos de acesso à informação."}, {"c": "dou-paragraph", "t": "O MINISTRO DE ESTADO DA AGRICULTURA E PECUÁRIA SUBSTITUTO, no uso da atribuição que lhe confere o art. 87, parágrafo único, inciso II, da Constituição, com base no inciso III do art. 1º do Decreto nº 8.851, de 20 de setembro de 2016, e tendo em vista o disposto na Lei nº 12.527, de 18 de novembro de 2011, no Decreto nº 7.724, de 16 de maio de 2012, no Decreto nº 8.777, de 11 de maio de 2016, no Decreto nº 11.529, de 16 de maio de 2023, no Decreto nº 12.642, de 1º de outubro de 2025, e o que consta do Processo nº 21000.051238/2026-11, resolve:"}, {"c": "dou-paragraph", "t": "CAPÍTULO I"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES PRELIMINARES"}, {"c": "dou-paragraph", "t": "Art. 1º Fica instituída a Rede de Acesso à Informação do Ministério da Agricultura e Pecuária - Rede SIC/MAPA e estabelecidos os procedimentos para tratamento dos pedidos de acesso à informação."}, {"c": "dou-paragraph", "t": "Art. 2º As disposições desta Portaria aplicam-se às unidades integrantes da Rede SIC/MAPA e aos agentes públicos, aos empregados públicos, aos colaboradores e às demais pessoas que, em razão de vínculo de qualquer natureza ou do exercício de atribuições junto ao Ministério da Agricultura e Pecuária, tenham acesso, guarda ou conhecimento de informações sob custódia deste Ministério."}, {"c": "dou-paragraph", "t": "CAPÍTULO II"}, {"c": "dou-paragraph", "t": "DA REDE SIC/MAPA"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Dos objetivos"}, {"c": "dou-paragraph", "t": "Art. 3º A Rede SIC/MAPA tem por objetivos:"}, {"c": "dou-paragraph", "t": "I - fortalecer a implementação da política de acesso à informação, no âmbito do Ministério da Agricultura e Pecuária, observando os princípios básicos da administração pública e as seguintes diretrizes dispostas no art. 3º da Lei nº 12.527, de 18 de novembro de 2011:"}, {"c": "dou-paragraph", "t": "a) observância da publicidade como preceito geral e do sigilo como exceção;"}, {"c": "dou-paragraph", "t": "b) divulgação de informações de interesse público, independentemente de solicitações;"}, {"c": "dou-paragraph", "t": "c) utilização de meios de comunicação viabilizados pela tecnologia da informação;"}, {"c": "dou-paragraph", "t": "d) fomento ao desenvolvimento da cultura de transparência; e"}, {"c": "dou-paragraph", "t": "e) desenvolvimento do controle social;"}, {"c": "dou-paragraph", "t": "II - estimular a transparência ativa, a abertura de dados e a divulgação de informações de interesse coletivo ou geral, observadas as hipóteses legais de sigilo e restrição de acesso;"}, {"c": "dou-paragraph", "t": "III - promover a articulação institucional entre as unidades integrantes do Ministério da Agricultura e Pecuária para o adequado cumprimento da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "IV - padronizar procedimentos, fluxos, entendimentos e orientações relacionados ao tratamento dos pedidos de acesso à informação;"}, {"c": "dou-paragraph", "t": "V - promover o compartilhamento de boas práticas, soluções e experiências entre as unidades integrantes da Rede SIC/MAPA;"}, {"c": "dou-paragraph", "t": "VI - incentivar a capacitação permanente dos agentes públicos envolvidos no tratamento dos pedidos de acesso à informação; e"}, {"c": "dou-paragraph", "t": "VII - contribuir para o cumprimento dos prazos, a qualidade das respostas e os demais indicadores relacionados à transparência e ao acesso à informação, no âmbito do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Parágrafo único. A Rede SIC/MAPA observará, ainda, as diretrizes, procedimentos complementares, entendimentos, enunciados e instruções expedidos pela Controladoria-Geral da União, a quem compete supervisionar a aplicação do disposto no art. 68 do Decreto nº 7.724, de 16 de maio de 2012, especialmente quanto ao cumprimento dos prazos e procedimentos pelos órgãos e entidades e à qualidade do serviço de acesso à informação."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Da organização e da composição"}, {"c": "dou-paragraph", "t": "Art. 4º A Rede SIC/MAPA será coordenada pela Secretaria-Executiva do Ministério da Agricultura e Pecuária, operacionalizada por intermédio da Ouvidoria do Ministério da Agricultura e Pecuária e compreenderá as seguintes unidades:"}, {"c": "dou-paragraph", "t": "I - o Serviço de Informação ao Cidadão - SIC;"}, {"c": "dou-paragraph", "t": "II - o Gabinete do Ministro;"}, {"c": "dou-paragraph", "t": "III - a Secretaria de Política Agrícola;"}, {"c": "dou-paragraph", "t": "IV - a Secretaria de Defesa Agropecuária;"}, {"c": "dou-paragraph", "t": "V - a Secretaria de Desenvolvimento Rural;"}, {"c": "dou-paragraph", "t": "VI - a Secretaria de Comércio e Relações Internacionais;"}, {"c": "dou-paragraph", "t": "VII - da Secretaria-Executiva:"}, {"c": "dou-paragraph", "t": "a) a Subsecretaria de Planejamento, Orçamento e Administração;"}, {"c": "dou-paragraph", "t": "b) a Subsecretaria de Tecnologia da Informação;"}, {"c": "dou-paragraph", "t": "c) a Subsecretaria de Gestão de Pessoas e de Gestão do Conhecimento;"}, {"c": "dou-paragraph", "t": "d) a Subsecretaria de Governança das Superintendências; e"}, {"c": "dou-paragraph", "t": "e) o Instituto Nacional de Meteorologia; e"}, {"c": "dou-paragraph", "t": "VIII - as Superintendências de Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Parágrafo único. O SIC de que trata o inciso I do caput integra a estrutura da Ouvidoria, à qual compete exercer sua coordenação e desempenhar as atribuições previstas no art. 9º da Lei nº 12.527, de 18 de novembro de 2011."}, {"c": "dou-paragraph", "t": "Art. 5º Os dirigentes das unidades que integram a Rede SIC/MAPA indicarão, no prazo de dez dias, contados da publicação desta Portaria, no mínimo, dois agentes públicos, titular e suplente, para, na qualidade de interlocutores, atuarem no tratamento dos pedidos de acesso à informação no âmbito de suas respectivas unidades."}, {"c": "dou-paragraph", "t": "§ 1º As indicações e eventuais substituições dos interlocutores de que trata o caput deverão ser encaminhadas à Ouvidoria por meio de ofício assinado pelo dirigente máximo da unidade correspondente."}, {"c": "dou-paragraph", "t": "§ 2º Observadas as necessidades da unidade, poderão ser indicados interlocutores adicionais, em número proporcional ao volume, à complexidade ou às especificidades das demandas de acesso à informação."}, {"c": "dou-paragraph", "t": "§ 3º Os indicados de que trata o caput deverão, respeitadas as especificidades dos órgãos:"}, {"c": "dou-paragraph", "t": "I - desempenhar funções que lhes possibilitem acesso ao dirigente máximo da respectiva unidade;"}, {"c": "dou-paragraph", "t": "II - possuir conhecimento a respeito da estrutura organizacional e das atribuições das áreas técnicas da unidade em que atuem;"}, {"c": "dou-paragraph", "t": "III - apresentar facilidade de comunicação e integração com as áreas técnicas da respectiva unidade; e"}, {"c": "dou-paragraph", "t": "IV - desempenhar as competências estabelecidas no art. 26."}, {"c": "dou-paragraph", "t": "CAPÍTULO III"}, {"c": "dou-paragraph", "t": "DOS PEDIDOS DE ACESSO À INFORMAÇÃO"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Do objeto dos pedidos"}, {"c": "dou-paragraph", "t": "Art. 6º Constituirá objeto de pedido de acesso à informação, formulado com fundamento na Lei nº 12.527, de 18 de novembro de 2011, a solicitação de documentos ou dados, processados ou não, que possam ser utilizados para produção e transmissão de conhecimento, contidos em qualquer meio, suporte ou formato, produzidos ou acumulados pelo Ministério da Agricultura e Pecuária, compreendendo, ainda:"}, {"c": "dou-paragraph", "t": "I - orientação sobre os procedimentos para a consecução de acesso, bem como sobre o local onde poderá ser encontrada ou obtida a informação;"}, {"c": "dou-paragraph", "t": "II - informação contida em registros ou documentos, produzidos ou acumulados, recolhidos ou não a arquivos públicos;"}, {"c": "dou-paragraph", "t": "III - informação produzida ou custodiada por pessoa física ou entidade privada decorrente de qualquer vínculo com o Ministério da Agricultura e Pecuária, mesmo que esse vínculo já tenha cessado;"}, {"c": "dou-paragraph", "t": "IV - informação primária, íntegra, autêntica e atualizada;"}, {"c": "dou-paragraph", "t": "V - informação sobre atividades exercidas, inclusive as relativas à sua política, organização e serviços;"}, {"c": "dou-paragraph", "t": "VI - informação pertinente à administração do patrimônio do órgão, utilização de recursos públicos, licitações e contratos administrativos; e"}, {"c": "dou-paragraph", "t": "VII - informação relativa:"}, {"c": "dou-paragraph", "t": "a) à implementação, ao acompanhamento e aos resultados dos programas, projetos e ações, bem como de metas e indicadores propostos; e"}, {"c": "dou-paragraph", "t": "b) ao resultado de inspeções, auditorias, prestações e tomadas de contas realizadas pelos órgãos de controle interno e externo, incluindo prestações de contas relativas a exercícios anteriores."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Dos requisitos do pedido"}, {"c": "dou-paragraph", "t": "Art. 7º O pedido de acesso à informação, nos termos do art. 12 do Decreto nº 7.724, de 16 de maio de 2012, deverá conter:"}, {"c": "dou-paragraph", "t": "I - nome do requerente;"}, {"c": "dou-paragraph", "t": "II - número de documento de identificação válido;"}, {"c": "dou-paragraph", "t": "III - especificação, de forma clara e precisa, da informação requerida; e"}, {"c": "dou-paragraph", "t": "IV - endereço físico ou eletrônico do requerente, para recebimento de comunicações ou da informação requerida."}, {"c": "dou-paragraph", "t": "§ 1º Será facultado ao requerente de acesso à informação, devidamente identificado no sistema eletrônico disponibilizado pela Controladoria-Geral da União para o registro e o atendimento aos pedidos de acesso à informação, optar pela preservação de sua identidade."}, {"c": "dou-paragraph", "t": "§ 2º É vedada qualquer exigência relativa aos motivos determinantes do pedido de acesso à informação."}, {"c": "dou-paragraph", "t": "§ 3º A identificação do requerente não poderá conter exigências que inviabilizem o exercício do direito de acesso à informação."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Do recebimento e da tramitação dos pedidos de acesso"}, {"c": "dou-paragraph", "t": "Art. 8º Os pedidos de acesso à informação serão recebidos:"}, {"c": "dou-paragraph", "t": "I - preferencialmente, por meio do sistema de acesso à informação fornecido pela Controladoria-Geral da União;"}, {"c": "dou-paragraph", "t": "II - por correspondência eletrônica, por meio do e-mail sic.mapa@agro.gov.br;"}, {"c": "dou-paragraph", "t": "III - por correspondência física, que deverá ser dirigida ao Ministério da Agricultura e Pecuária, por meio do endereço Esplanada dos Ministérios, Bloco D, Edifício-Sede, CEP 70043-900, Brasília/DF; e"}, {"c": "dou-paragraph", "t": "IV - presencialmente, nas dependências do SIC, na Esplanada dos Ministérios, Bloco D, Edifício-Sede, Brasília/DF."}, {"c": "dou-paragraph", "t": "§ 1º Os pedidos de acesso à informação recebidos por qualquer outra unidade do Ministério da Agricultura e Pecuária deverão, na data de seu recebimento, ser encaminhados ao SIC para registro no sistema de acesso à informação, nos termos do art. 11-A, § 2º, do Decreto nº 7.724, de 16 de maio de 2012, da seguinte forma:"}, {"c": "dou-paragraph", "t": "I - os pedidos de acesso à informação recebidos por meio de e-mails institucionais deverão ser encaminhados ao SIC, por intermédio do endereço eletrônico sic.mapa@agro.gov.br;"}, {"c": "dou-paragraph", "t": "II - os pedidos recebidos por meio do Sistema Eletrônico de Informações - SEI deverão ser encaminhados à unidade do SIC, mediante despacho de encaminhamento; e"}, {"c": "dou-paragraph", "t": "III - os pedidos recebidos por meio de correspondência física deverão ser digitalizados e autuados no SEI, para posterior encaminhamento ao SIC, na forma do inciso II."}, {"c": "dou-paragraph", "t": "§ 2º O SIC disponibilizará atendimento telefônico, por meio dos contatos divulgados no sítio eletrônico do Ministério da Agricultura e Pecuária, com a finalidade de orientar o cidadão quanto à utilização do sistema eletrônico disponibilizado pela Controladoria-Geral da União e fornecer informações disponibilizadas em transparência ativa."}, {"c": "dou-paragraph", "t": "Art. 9º O SEI será utilizado para a tramitação, organização e acompanhamento dos fluxos internos relacionados ao tratamento dos pedidos de acesso e recursos, no âmbito do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "CAPÍTULO IV"}, {"c": "dou-paragraph", "t": "DO FORNECIMENTO DAS INFORMAÇÕES"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Do fornecimento e da disponibilização da informação"}, {"c": "dou-paragraph", "t": "Art. 10. O fornecimento de informação será gratuito, salvo quando o serviço de busca e fornecimento exigir a reprodução de documentos."}, {"c": "dou-paragraph", "t": "§ 1º Quando o fornecimento da informação implicar a reprodução de documentos, serão disponibilizadas gratuitamente até dez páginas e, acima desse limite, será emitida Guia de Recolhimento da União ou documento equivalente, considerando o número total de cópias para fins de ressarcimento dos custos dos serviços e dos materiais utilizados."}, {"c": "dou-paragraph", "t": "§ 2º A comprovação do pagamento da Guia de Recolhimento da União deverá ser encaminhada ao SIC, em até dez dias, por meio de correio eletrônico, correspondência física ou entrega presencial, contados da data de recebimento da resposta do SIC com as orientações para pagamento."}, {"c": "dou-paragraph", "t": "§ 3º A unidade administrativa responsável providenciará e encaminhará a informação ao SIC, no prazo de até dez dias, contados da data de recebimento da comprovação do pagamento da Guia de Recolhimento da União, para entrega ao requerente."}, {"c": "dou-paragraph", "t": "§ 4º Estará isento de ressarcir os custos previstos no § 1º aquele cuja situação econômica não lhe permita fazê-lo sem prejuízo do próprio sustento ou do sustento da família, mediante declaração, nos termos da Lei nº 7.115, de 29 de agosto de 1983."}, {"c": "dou-paragraph", "t": "Art. 11. O acesso à informação disponível deverá ser concedido imediatamente, sempre que possível."}, {"c": "dou-paragraph", "t": "§ 1º Não sendo possível o acesso imediato, a resposta deverá ser apresentada no prazo legal, observado o disposto nos arts. 38 a 42."}, {"c": "dou-paragraph", "t": "§ 2º Quando a informação solicitada estiver disponível em transparência ativa ou em outro meio de acesso universal, a resposta deverá orientar o requerente quanto ao local e à forma para sua consulta, obtenção ou reprodução, acompanhada de passo a passo que explique claramente como localizar a informação demandada."}, {"c": "dou-paragraph", "t": "§ 3º O encaminhamento das orientações de que trata o § 2º desobriga o fornecimento direto da informação, salvo quando o requerente declarar não dispor de meios para acessá-la."}, {"c": "dou-paragraph", "t": "Art. 12. Quando o volume de informações não for suportado pelo sistema de acesso à informação, estas poderão ser encaminhadas por outros meios, desde que seja devidamente informado ao requerente."}, {"c": "dou-paragraph", "t": "Parágrafo único. Na hipótese prevista no caput, a informação poderá ser disponibilizada por meio de serviço de armazenamento em nuvem, acompanhada de orientações para acesso e do prazo para realização do download, mediante entrega na sede do SIC ou por correspondência eletrônica, quando o requerente estiver identificado."}, {"c": "dou-paragraph", "t": "Art. 13. Os pedidos de acesso à informação submetidos ao Ministério da Agricultura e Pecuária não serão atendidos quando forem:"}, {"c": "dou-paragraph", "t": "I - genéricos: pedidos inespecíficos que não descrevam de forma delimitada o objeto da solicitação;"}, {"c": "dou-paragraph", "t": "II - desproporcionais: pedidos que comprometam significativamente a realização das atividades regulares das unidades do Ministério, acarretando prejuízo injustificado aos direitos de outros solicitantes;"}, {"c": "dou-paragraph", "t": "III - desarrazoados: pedidos não amparados pela Lei nº 12.527, de 18 de novembro de 2011, ou pelas garantias fundamentais previstas na Constituição Federal ou, ainda, contrários aos interesses públicos e aos princípios da segurança pública, celeridade e economicidade da Administração Pública;"}, {"c": "dou-paragraph", "t": "IV - incompreensíveis: o teor do pedido não permite compreender qual a informação desejada, impossibilitando o atendimento;"}, {"c": "dou-paragraph", "t": "V - duplicados ou repetidos: o mesmo pedido cadastrado mais de uma vez, com mesmo solicitante e teor idêntico;"}, {"c": "dou-paragraph", "t": "VI - exigir trabalhos adicionais de análise, interpretação ou consolidação de dados e informações, tais como:"}, {"c": "dou-paragraph", "t": "a) orientação sobre a aplicação de legislações ou sobre a interpretação de determinado dispositivo legal; ou"}, {"c": "dou-paragraph", "t": "b) pesquisas estruturadas que demandem a produção ou a consolidação de informações;"}, {"c": "dou-paragraph", "t": "VII - não relacionados às competências do Ministério;"}, {"c": "dou-paragraph", "t": "VIII - relacionados à prestação de serviços do Ministério, quando houver canal específico e efetivo para essa finalidade;"}, {"c": "dou-paragraph", "t": "IX - solicitar providências administrativas;"}, {"c": "dou-paragraph", "t": "X - demandar posicionamento ou manifestação das unidades do Ministério;"}, {"c": "dou-paragraph", "t": "XI - caracterizados como reclamações, solicitações de providências, denúncias e sugestões; e"}, {"c": "dou-paragraph", "t": "XII - requerimentos ou solicitações formulados por servidor público do Ministério relativos à sua situação funcional, quando houver canal específico para atendimento, hipótese em que o interessado deverá dirigir sua solicitação à unidade de gestão de pessoas à qual esteja vinculado."}, {"c": "dou-paragraph", "t": "Art. 14. As negativas de acesso à informação deverão, quando se tratar de pedido considerado:"}, {"c": "dou-paragraph", "t": "I - genérico, demonstrar que a solicitação não possui elementos básicos para a definição precisa de seu objeto;"}, {"c": "dou-paragraph", "t": "II - desproporcional, demonstrar as razões da recusa total ou parcial da demanda, apresentando os impactos negativos nas demais atividades do órgão;"}, {"c": "dou-paragraph", "t": "III - desarrazoado, ser fundamentadas quanto à desconformidade com o interesse público, a segurança pública, a celeridade ou a economicidade da Administração Pública;"}, {"c": "dou-paragraph", "t": "IV - de trabalho adicional de análise, interpretação ou consolidação de dados e informações, sempre que possível, indicar o local onde se encontram as informações necessárias para que o próprio requerente realize a interpretação, consolidação ou tratamento dos dados; e"}, {"c": "dou-paragraph", "t": "V - que não seja de competência do Ministério da Agricultura e Pecuária, indicar, sempre que possível, o órgão ou entidade competente para o fornecimento da informação."}, {"c": "dou-paragraph", "t": "Parágrafo único. O direito de acesso aos documentos ou às informações neles contidas utilizados como fundamento da tomada de decisão e do ato administrativo será assegurado com a edição do ato decisório respectivo."}, {"c": "dou-paragraph", "t": "Art. 15. Quando o acesso à informação for negado em razão de classificação de sigilo, a resposta ao requerente deverá conter os fundamentos da negativa, a indicação da autoridade classificadora responsável pela decisão e a informação acerca da possibilidade de apresentação de pedido de desclassificação da informação, nos termos da legislação vigente."}, {"c": "dou-paragraph", "t": "Parágrafo único. Na hipótese prevista no caput, deverá ser informado ao requerente o procedimento para apresentação do pedido de desclassificação, bem como a autoridade competente para sua apreciação, observado o disposto no art. 19, caput, inciso III, do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "Art. 16. Quando se tratar de acesso à informação contida em documento cuja manipulação possa prejudicar sua integridade, deverá ser oferecida a consulta de cópia, com certificação de que esta confere com o original."}, {"c": "dou-paragraph", "t": "Parágrafo único. Na impossibilidade de obtenção de cópia, o interessado poderá solicitar que a reprodução seja realizada por outro meio, às suas expensas e sob supervisão de servidor público, desde que não comprometa a conservação do documento original."}, {"c": "dou-paragraph", "t": "Art. 17. No ato da entrega da informação, o SIC deverá informar ao requerente sobre a possibilidade de interposição de recurso."}, {"c": "dou-paragraph", "t": "Parágrafo único. Caso o cidadão tenha interesse em interpor recurso após a disponibilização da informação, deverá ser informado pelo SIC de que poderá fazê-lo no prazo de dez dias, contado da data de entrega da informação."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Das informações pessoais"}, {"c": "dou-paragraph", "t": "Art. 18. O tratamento, o acesso, a restrição de acesso e a proteção das informações pessoais, no âmbito do Ministério da Agricultura e Pecuária, observarão o disposto no art. 31 da Lei nº 12.527, de 18 de novembro de 2011, e nos arts. 55 a 62 do Decreto nº 7.724, de 16 de maio de 2012, sem prejuízo dos procedimentos específicos estabelecidos nesta Portaria."}, {"c": "dou-paragraph", "t": "Art. 19. O pedido de acesso a informações pessoais formulado pelo próprio titular observará os procedimentos previstos nesta Portaria e estará condicionado à comprovação de sua identidade, nos termos do art. 60 do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "§ 1º Considera-se comprovada a identidade do requerente quando o pedido for apresentado por meio do sistema de acesso à informação mediante autenticação em conta Gov.br com nível de confiabilidade Prata ou Ouro."}, {"c": "dou-paragraph", "t": "§ 2º Quando a autenticação não ocorrer na forma prevista no § 1º, o SIC poderá solicitar documentação complementar ou adotar outros procedimentos idôneos destinados à confirmação da identidade do requerente, previamente ao fornecimento da informação."}, {"c": "dou-paragraph", "t": "§ 3º Comprovada a identidade do requerente, as informações pessoais poderão ser disponibilizadas por meio eletrônico, desde que adotadas medidas aptas a preservar sua confidencialidade e integridade."}, {"c": "dou-paragraph", "t": "§ 4º O pedido de acesso a informações pessoais formulado por terceiro observará o disposto no art. 61 do Decreto nº 7.724, de 16 de maio de 2012, e deverá estar acompanhado da documentação comprobatória pertinente à hipótese legal invocada."}, {"c": "dou-paragraph", "t": "§ 5º A procuração encaminhada por meio do sistema de acesso à informação poderá ser aceita quando sua autenticidade puder ser verificada pelos meios disponíveis à Administração."}, {"c": "dou-paragraph", "t": "Art. 20. O acesso a informações pessoais por terceiros será condicionado à assinatura de termo de responsabilidade, conforme modelo constante do Anexo, que disporá sobre a finalidade e a destinação que fundamentaram a autorização de acesso, bem como sobre as obrigações assumidas pelo requerente."}, {"c": "dou-paragraph", "t": "§ 1º A utilização das informações pessoais ficará vinculada à finalidade que fundamentou a autorização de acesso, vedada sua utilização para finalidade diversa."}, {"c": "dou-paragraph", "t": "§ 2º A utilização indevida das informações pessoais sujeitará o responsável às sanções previstas na legislação aplicável."}, {"c": "dou-paragraph", "t": "Art. 21. A existência de informações pessoais em documentos, processos ou bases de dados não constituirá, por si só, fundamento para a negativa integral de acesso à informação."}, {"c": "dou-paragraph", "t": "Parágrafo único. Sempre que possível, deverão ser adotadas medidas de tratamento da informação, inclusive mediante ocultação, anonimização, pseudonimização, tarjamento, exclusão ou descaracterização de dados pessoais, de modo a viabilizar o acesso à parcela da informação não sujeita à restrição de acesso."}, {"c": "dou-paragraph", "t": "CAPÍTULO V"}, {"c": "dou-paragraph", "t": "DOS AGENTES, DAS COMPETÊNCIAS E DO TRATAMENTO"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Dos agentes responsáveis"}, {"c": "dou-paragraph", "t": "Art. 22. Os agentes públicos responsáveis pelo tratamento dos pedidos de acesso à informação serão identificados de acordo com os seguintes perfis:"}, {"c": "dou-paragraph", "t": "I - representante do SIC: servidor responsável pelo SIC;"}, {"c": "dou-paragraph", "t": "II - interlocutor: agente público designado pelo dirigente máximo da unidade para atuar no tratamento dos pedidos de acesso à informação, no âmbito de sua unidade; e"}, {"c": "dou-paragraph", "t": "III - responsável técnico: agente público responsável pela validação, assinatura e encaminhamento das respostas aos pedidos de acesso à informação, no âmbito de sua unidade, observada a seguinte estrutura de cargos:"}, {"c": "dou-paragraph", "t": "a) nos órgãos de assistência direta e imediata ao Ministro:"}, {"c": "dou-paragraph", "t": "1. o Coordenador-Geral do Gabinete, no Gabinete;"}, {"c": "dou-paragraph", "t": "2. os Chefes de Assessoria, nas respectivas Assessorias;"}, {"c": "dou-paragraph", "t": "3. o Ouvidor, na Ouvidoria;"}, {"c": "dou-paragraph", "t": "4. o Corregedor, na Corregedoria; e"}, {"c": "dou-paragraph", "t": "5. o Consultor Jurídico, na Consultoria Jurídica;"}, {"c": "dou-paragraph", "t": "6. os Subsecretários, nas respectivas Subsecretarias da Secretaria-Executiva;"}, {"c": "dou-paragraph", "t": "7. o Diretor, no Instituto Nacional de Meteorologia da Secretaria-Executiva;"}, {"c": "dou-paragraph", "t": "b) nas Secretarias de que tratam os incisos III a VII do caput do art. 4º, os respectivos Diretores; e"}, {"c": "dou-paragraph", "t": "c) nas Superintendências de Agricultura e Pecuária, os respectivos Superintendentes."}, {"c": "dou-paragraph", "t": "Parágrafo único. O servidor de que trata o inciso I do caput atuará em conformidade com as atribuições previstas no art. 9º da Lei nº 12.527, de 18 de novembro de 2011, e com as competências estabelecidas no art. 25."}, {"c": "dou-paragraph", "t": "Art. 23. As autoridades hierárquicas responsáveis pelas decisões dos recursos em primeira instância, de que trata o art. 15 da Lei nº 12.527, de 18 de novembro de 2011, serão identificadas de acordo com os seguintes cargos:"}, {"c": "dou-paragraph", "t": "I - o Chefe de Gabinete do Ministro, quando se tratar de recursos apresentados no âmbito dos seguintes órgãos:"}, {"c": "dou-paragraph", "t": "a) Coordenação-Geral do Gabinete;"}, {"c": "dou-paragraph", "t": "b) Assessorias;"}, {"c": "dou-paragraph", "t": "c) Ouvidoria;"}, {"c": "dou-paragraph", "t": "d) Corregedoria; e"}, {"c": "dou-paragraph", "t": "e) Consultoria Jurídica;"}, {"c": "dou-paragraph", "t": "II - o Secretário-Executivo, quando se tratar de recursos apresentados no âmbito das Subsecretarias, do Instituto Nacional de Meteorologia e na hipótese prevista no art. 31, parágrafo único;"}, {"c": "dou-paragraph", "t": "III - os Secretários, quando se tratar de recursos apresentados no âmbito dos Departamentos de suas respectivas Secretarias; e"}, {"c": "dou-paragraph", "t": "IV - o Subsecretário de Gestão das Superintendências ou cargo equivalente, quando se tratar de recursos apresentados no âmbito das Superintendências de Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 1º Quando a resposta ao pedido de acesso à informação for elaborada diretamente pelo SIC, o recurso em primeira instância será decidido pelo Ouvidor."}, {"c": "dou-paragraph", "t": "§ 2º Quando a resposta fornecida diretamente pelo SIC for fundamentada em manifestação previamente homologada pela unidade competente ou quando a informação solicitada estiver disponível em transparência ativa, o recurso em primeira instância será submetido à autoridade hierárquica da unidade responsável pela informação para decisão."}, {"c": "dou-paragraph", "t": "Art. 24. Os recursos negados em primeira instância serão apreciados, em segunda instância, pelo Ministro de Estado da Agricultura e Pecuária ou por seu substituto legal."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Das competências e do tratamento"}, {"c": "dou-paragraph", "t": "Subseção I"}, {"c": "dou-paragraph", "t": "Do representante do SIC"}, {"c": "dou-paragraph", "t": "Art. 25. Compete ao representante do SIC de que trata o inciso I do art. 22 assegurar o atendimento aos pedidos de acesso à informação e aos recursos apresentados ao Ministério da Agricultura e Pecuária, mediante as seguintes atribuições:"}, {"c": "dou-paragraph", "t": "I - receber e realizar análise prévia dos pedidos de acesso à informação e dos recursos;"}, {"c": "dou-paragraph", "t": "II - promover o encaminhamento do requerimento ao órgão ou entidade competente, por meio do sistema de acesso à informação, quando não se tratar de matéria de competência do Ministério e o destinatário possuir cadastro ativo na plataforma;"}, {"c": "dou-paragraph", "t": "III - verificar a existência de informação disponível em transparência ativa, de precedentes publicados pela Controladoria-Geral da União ou de resposta previamente homologada pela unidade competente, que permita o atendimento direto do requerimento pelo SIC;"}, {"c": "dou-paragraph", "t": "IV - encaminhar o pedido ao interlocutor da unidade competente, mediante formulário de encaminhamento no SEI, quando não houver informação disponível ou quando não for possível atestar sua adequação ao caso concreto;"}, {"c": "dou-paragraph", "t": "V - comunicar ao requerente a necessidade de dilação de prazo para a resposta, quando cabível;"}, {"c": "dou-paragraph", "t": "VI - registrar, no sistema de acesso à informação, a resposta recebida para encaminhamento ao requerente, identificando a unidade responsável pela sua elaboração;"}, {"c": "dou-paragraph", "t": "VII - informar ao requerente sobre o direito de interpor recurso nos casos de negativa de acesso à informação ou de ausência de apresentação das razões da negativa;"}, {"c": "dou-paragraph", "t": "VIII - orientar que as respostas sejam redigidas em linguagem simples, clara e acessível, evitando o uso de jargões ou termos técnicos desnecessários;"}, {"c": "dou-paragraph", "t": "IX - propor às unidades a inclusão, no sítio eletrônico do Ministério, de informações frequentemente solicitadas pelos cidadãos, com vistas ao fortalecimento da transparência ativa;"}, {"c": "dou-paragraph", "t": "X - fomentar, junto às unidades competentes, a elaboração, homologação e atualização de respostas padrão para atendimento de pedidos recorrentes de acesso à informação;"}, {"c": "dou-paragraph", "t": "XI - propor ações destinadas ao aprimoramento da qualidade e à uniformização dos procedimentos internos junto aos demais integrantes da Rede SIC/MAPA;"}, {"c": "dou-paragraph", "t": "XII - elaborar relatório anual de que trata o art. 45 do Decreto nº 7.724, de 16 de maio de 2012;"}, {"c": "dou-paragraph", "t": "XIII - atuar em coordenação com a Comissão Permanente de Avaliação de Documentos Sigilosos - CPADS/MAPA e com as instâncias do Sistema de Integridade, Transparência e Acesso à Informação da Administração Pública Federal - Sitai, observadas as diretrizes da Controladoria-Geral da União; e"}, {"c": "dou-paragraph", "t": "XIV - encaminhar os casos de omissões e as reclamações à Autoridade de Monitoramento para conhecimento e providências cabíveis, de acordo com o disposto no art. 67, caput, inciso V, do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "§ 1º Quando o pedido envolver matéria de competência de mais de uma unidade, o requerimento será encaminhado a todas as unidades responsáveis pela prestação das informações e o SIC ficará responsável pela consolidação das respostas."}, {"c": "dou-paragraph", "t": "§ 2º O SIC submeterá à apreciação da Secretaria-Executiva os pedidos de acesso à informação que envolvam matéria de relevante repercussão institucional ou demandem alinhamento entre as manifestações de duas ou mais unidades administrativas."}, {"c": "dou-paragraph", "t": "§ 3º Na hipótese prevista no inciso II do caput, quando o órgão ou entidade competente não possuir cadastro ativo no sistema de acesso à informação, o SIC concluirá o pedido, indicando ao requerente, sempre que possível, o órgão ou entidade que detém a informação solicitada."}, {"c": "dou-paragraph", "t": "§ 4º Para os efeitos do inciso III do caput, quando a informação disponível demandar validação quanto à sua confiabilidade, integridade ou autenticidade, o SIC deverá encaminhar o pedido ao interlocutor da unidade competente, estabelecendo prazo para manifestação."}, {"c": "dou-paragraph", "t": "§ 5º Na hipótese de necessidade de retificação ou complementação da resposta, o SIC encaminhará a solicitação ao interlocutor da unidade competente, com a indicação dos ajustes necessários."}, {"c": "dou-paragraph", "t": "Subseção II"}, {"c": "dou-paragraph", "t": "Dos interlocutores"}, {"c": "dou-paragraph", "t": "Art. 26. Compete ao interlocutor:"}, {"c": "dou-paragraph", "t": "I - receber e analisar os pedidos de acesso à informação submetidos pelo SIC e encaminhá-los ao responsável técnico, conforme qualificados no art. 22, caput, inciso III, para elaboração de resposta;"}, {"c": "dou-paragraph", "t": "II - devolver imediatamente o pedido ao SIC quando a informação não estiver sob a competência de sua unidade, fornecendo, sempre que possível, informações sobre a área, o órgão ou a entidade competente;"}, {"c": "dou-paragraph", "t": "III - manter canais de comunicação com as demais instâncias de sua esfera de atuação e, quando necessário, com outras unidades relacionadas à informação solicitada, com vistas ao adequado encaminhamento e tratamento dos pedidos de acesso à informação;"}, {"c": "dou-paragraph", "t": "IV - analisar a resposta elaborada pelo responsável técnico e, quando necessário, orientá-lo quanto à qualidade da resposta e à necessidade de fundamentação da negativa de acesso à informação;"}, {"c": "dou-paragraph", "t": "V - verificar o adequado tratamento das informações pessoais, sigilosas ou sujeitas a restrição de acesso e orientar o responsável técnico quanto às medidas necessárias à proteção dessas informações antes do encaminhamento da resposta ao SIC;"}, {"c": "dou-paragraph", "t": "VI - verificar se a resposta ao pedido de acesso à informação foi devidamente assinada pelo responsável técnico e, quando necessário, devolvê-la para ajuste;"}, {"c": "dou-paragraph", "t": "VII - encaminhar ao SIC, mediante despacho, a resposta elaborada pelo responsável técnico, observados os trâmites aplicáveis;"}, {"c": "dou-paragraph", "t": "VIII - receber os recursos e proceder ao seu encaminhamento conforme as autoridades hierárquicas definidas no art. 23; e"}, {"c": "dou-paragraph", "t": "IX - observar o cumprimento dos prazos previstos nos arts. 38 a 42."}, {"c": "dou-paragraph", "t": "Subseção III"}, {"c": "dou-paragraph", "t": "Dos responsáveis técnicos"}, {"c": "dou-paragraph", "t": "Art. 27. Compete ao responsável técnico as seguintes atribuições:"}, {"c": "dou-paragraph", "t": "I - verificar se a informação solicitada se encontra disponível em transparência ativa e, quando for o caso, indicar ao requerente o local e a forma de acesso, inclusive por meio de link eletrônico e de orientações claras para sua localização, de modo a possibilitar o atendimento imediato do pedido;"}, {"c": "dou-paragraph", "t": "II - verificar a existência de precedentes relacionados a pedidos de acesso à informação sobre matéria semelhante, com vistas a assegurar a uniformidade de entendimento e a consistência das respostas;"}, {"c": "dou-paragraph", "t": "III - assegurar que as respostas aos pedidos de acesso à informação sob sua responsabilidade sejam redigidas de forma clara, objetiva, simples e de fácil compreensão, evitando o uso desnecessário de siglas, termos técnicos ou estrangeirismos, observado o disposto no art. 5º da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "IV - formalizar ao interlocutor de sua unidade a necessidade de dilação de prazo para o fornecimento de resposta ao cidadão, por meio da apresentação de justificativa expressa, conforme o disposto no art. 11, § 2º, da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "V - apresentar justificativa para a negativa de acesso à informação, total ou parcial, quando for o caso, com fundamento na Lei nº 12.527, de 18 de novembro de 2011, ou em outras hipóteses legais de restrição de acesso;"}, {"c": "dou-paragraph", "t": "VI - assinar e encaminhar ao interlocutor as respostas aos pedidos de acesso à informação afetos à sua unidade, ainda que sua instrução tenha contado com subsídios fornecidos por unidades sob sua subordinação;"}, {"c": "dou-paragraph", "t": "VII - prestar informações e subsídios técnicos para a apreciação dos recursos interpostos em face das respostas aos pedidos de acesso à informação sob sua responsabilidade;"}, {"c": "dou-paragraph", "t": "VIII - avaliar e propor a inclusão, no sítio eletrônico do Ministério da Agricultura e Pecuária, de informações frequentemente solicitadas pelos cidadãos, com vistas ao fortalecimento da transparência ativa, desde que certificada sua natureza pública;"}, {"c": "dou-paragraph", "t": "IX - elaborar, homologar e atualizar, quando cabível, respostas padrão para atendimento de pedidos recorrentes de acesso à informação e submetê-las ao SIC para utilização; e"}, {"c": "dou-paragraph", "t": "X - assegurar o cumprimento dos prazos previstos nos arts. 38 a 42."}, {"c": "dou-paragraph", "t": "Subseção IV"}, {"c": "dou-paragraph", "t": "Dos dirigentes"}, {"c": "dou-paragraph", "t": "Art. 28. Compete aos dirigentes:"}, {"c": "dou-paragraph", "t": "I - analisar e decidir sobre os recursos apresentados pelo requerente em razão da negativa de acesso às informações solicitadas no âmbito de sua unidade;"}, {"c": "dou-paragraph", "t": "II - receber, analisar e adotar providências a respeito das reclamações apresentadas à Autoridade de Monitoramento de que trata o art. 47 em razão dos casos de omissão de informações no âmbito de sua unidade, conforme o previsto no art. 40 da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "III - prover subsídios que apoiem o Ministro de Estado da Agricultura e Pecuária na avaliação dos recursos interpostos em segunda instância, decorrentes de decisões que negaram o acesso à informação sob a responsabilidade da unidade;"}, {"c": "dou-paragraph", "t": "IV - fornecer esclarecimentos à Controladoria-Geral da União e à Comissão Mista de Reavaliação de Informações necessários à decisão dos recursos apresentados em terceira e quarta instâncias, respectivamente, relativos a sua unidade; e"}, {"c": "dou-paragraph", "t": "V - assegurar a conformidade das informações da unidade com as disposições da Lei nº 12.527, de 18 de novembro de 2011, bem como a observância dos prazos, a clareza nas respostas e a aderência aos procedimentos de transparência ativa."}, {"c": "dou-paragraph", "t": "Subseção V"}, {"c": "dou-paragraph", "t": "Do Ministro de Estado da Agricultura e Pecuária"}, {"c": "dou-paragraph", "t": "Art. 29. Compete ao Ministro de Estado da Agricultura e Pecuária:"}, {"c": "dou-paragraph", "t": "I - decidir sobre os recursos apresentados em grau de segunda instância, referentes à negativa de acesso à informação, no âmbito do Ministério;"}, {"c": "dou-paragraph", "t": "II - classificar as informações nos graus de sigilo ultrassecreto, secreto e reservado e exercer a competência para delegar essa atribuição, observado o disposto no art. 27 da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "III - determinar a publicação anual, no sítio eletrônico do Ministério, do rol de informações desclassificadas, do rol de documentos classificados por grau de sigilo e do relatório estatístico dos pedidos de acesso à informação, na forma do art. 30 da Lei nº 12.527, de 18 de novembro de 2011; e"}, {"c": "dou-paragraph", "t": "IV - aprovar diretrizes e normas relacionadas à Lei nº 12.527, de 18 de novembro de 2011, e apoiar medidas destinadas ao aprimoramento da transparência e do acesso à informação, no âmbito do Ministério, em consonância com a Política de Transparência e Acesso à Informação do Governo Federal."}, {"c": "dou-paragraph", "t": "CAPÍTULO VI"}, {"c": "dou-paragraph", "t": "DOS RECURSOS"}, {"c": "dou-paragraph", "t": "Art. 30. Negado o acesso à informação ou não apresentadas as razões da negativa, o requerente poderá interpor recurso, no prazo de dez dias, contados da data de recebimento da negativa, observadas as disposições da Lei nº 12.527, de 18 de novembro de 2011, e seus regulamentos."}, {"c": "dou-paragraph", "t": "Art. 31. Interposto recurso em primeira instância, o SIC realizará análise preliminar e o encaminhará ao interlocutor da unidade responsável pela resposta recorrida."}, {"c": "dou-paragraph", "t": "Parágrafo único. Quando o recurso recair sobre pedido de acesso à informação cuja resposta tenha sido elaborada por mais de uma unidade sujeita a autoridades recursais distintas, caberá ao Secretário-Executivo apreciar e decidir o recurso em primeira instância."}, {"c": "dou-paragraph", "t": "Art. 32. Interposto recurso em segunda instância, o SIC encaminhará o processo ao interlocutor da unidade competente pela resposta inicial para submissão ao dirigente responsável pelo recurso em primeira instância, bem como à Autoridade de Monitoramento, para subsidiar a decisão do Ministro da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 33. A apreciação dos recursos observará as seguintes instâncias recursais:"}, {"c": "dou-paragraph", "t": "I - instâncias recursais internas, correspondentes às autoridades responsáveis pela apreciação dos recursos em primeira e segunda instâncias, definidas nos arts. 28 e 29, observada a hierarquia recursal prevista no art. 15 da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "II - Controladoria-Geral da União; e"}, {"c": "dou-paragraph", "t": "III - Comissão Mista de Reavaliação de Informações."}, {"c": "dou-paragraph", "t": "Art. 34. As decisões proferidas em sede recursal deverão indicar, de forma clara e fundamentada, os motivos de fato e de direito que as embasam, especialmente quando mantida a negativa de acesso à informação."}, {"c": "dou-paragraph", "t": "Art. 35. Quando a decisão recursal determinar o fornecimento da informação, deverão ser adotadas as providências necessárias ao seu atendimento, observadas as disposições legais relativas à proteção de informações pessoais, sigilosas ou sujeitas a restrição de acesso."}, {"c": "dou-paragraph", "t": "Art. 36. Os recursos interpostos perante a Controladoria-Geral da União e a Comissão Mista de Reavaliação de Informações serão instruídos com as informações e manifestações necessárias à adequada apreciação da matéria, observados os procedimentos, as orientações e os prazos estabelecidos por essas instâncias."}, {"c": "dou-paragraph", "t": "CAPÍTULO VII"}, {"c": "dou-paragraph", "t": "DA OMISSÃO E DA RECLAMAÇÃO"}, {"c": "dou-paragraph", "t": "Art. 37. Considera-se omissão, para os fins da Lei nº 12.527, de 18 de novembro de 2011, e do Decreto nº 7.724, de 16 de maio de 2012, a ausência de manifestação da autoridade competente quanto ao pedido de acesso à informação, após o decurso dos prazos legalmente estabelecidos."}, {"c": "dou-paragraph", "t": "§ 1º A omissão na apreciação do pedido de acesso à informação sujeita-se ao procedimento de reclamação dirigido à Autoridade de Monitoramento da Lei nº 12.527, de 18 de novembro de 2011, nos termos do art. 22 do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "§ 2º A omissão na apreciação do recurso será tratada de acordo com as disposições recursais previstas na Lei nº 12.527, de 18 de novembro de 2011, e no Decreto nº 7.724, de 16 de maio de 2012, assegurado ao requerente o acesso às instâncias competentes para apreciação da matéria."}, {"c": "dou-paragraph", "t": "§ 3º Na hipótese de descumprimento do disposto no caput, a Autoridade de Monitoramento da Lei nº 12.527, de 18 de novembro de 2011, poderá comunicar o fato à Corregedoria do Ministério da Agricultura e Pecuária, quando houver indícios da prática de conduta passível de responsabilização, para apuração na forma da legislação aplicável."}, {"c": "dou-paragraph", "t": "CAPÍTULO VIII"}, {"c": "dou-paragraph", "t": "DOS PRAZOS"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Dos pedidos de acesso à informação"}, {"c": "dou-paragraph", "t": "Art. 38. Os pedidos de acesso à informação deverão ser respondidos no prazo de até vinte dias, contados da data de seu registro no sistema de acesso à informação."}, {"c": "dou-paragraph", "t": "Parágrafo único. O prazo previsto no caput poderá ser prorrogado, uma única vez, por até dez dias, mediante justificativa expressa do responsável técnico, da qual será cientificado o requerente antes do término do prazo inicialmente estabelecido, nos termos do art. 11, § 2º, da Lei nº 12.527, de 18 de novembro de 2011."}, {"c": "dou-paragraph", "t": "Art. 39. Para assegurar o cumprimento dos prazos legais previstos no art. 38, as unidades responsáveis pela informação deverão adotar os fluxos internos que julgarem necessários para que a resposta seja encaminhada ao SIC no prazo de até quinze dias, contados da data de recebimento do pedido."}, {"c": "dou-paragraph", "t": "Parágrafo único. O prazo previsto no caput compreenderá todas as etapas necessárias à elaboração, à análise, à revisão, à assinatura e ao encaminhamento da resposta ao SIC."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Dos recursos"}, {"c": "dou-paragraph", "t": "Art. 40. As decisões sobre os recursos interpostos em grau de primeira e segunda instância deverão ser proferidas no prazo de até cinco dias, contados da data de seu recebimento, conforme estabelecido no art. 21 do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "§ 1º Ao receber os recursos de que trata o caput, o SIC deverá preencher o formulário de encaminhamento no SEI, considerando o prazo estabelecido no sistema de acesso à informação, estipulando prazo interno para retorno da decisão."}, {"c": "dou-paragraph", "t": "§ 2º Para assegurar o cumprimento dos prazos legais previstos no caput, as unidades responsáveis pela instrução e decisão dos recursos deverão adotar os fluxos internos que julgarem necessários para que a resposta seja encaminhada ao SIC no prazo estabelecido nos formulários de encaminhamento dos recursos."}, {"c": "dou-paragraph", "t": "Art. 41. A inobservância dos prazos internos estabelecidos nos formulários de encaminhamentos dos recursos não afastará o dever de cumprimento dos prazos legais previstos na Lei nº 12.527, de 18 de novembro de 2011."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Das reclamações por omissões"}, {"c": "dou-paragraph", "t": "Art. 42. Na hipótese de omissão de resposta ao pedido de acesso à informação, o requerente poderá apresentar reclamação à Autoridade de Monitoramento da Lei nº 12.527, de 18 de novembro de 2011, no prazo de dez dias, contados da data de vencimento do prazo para resposta."}, {"c": "dou-paragraph", "t": "§ 1º A Autoridade de Monitoramento manifestar-se-á no prazo de cinco dias, contados da data de recebimento da reclamação nos termos do art. 22 do Decreto nº 7.724, de 16 de maio de 2012."}, {"c": "dou-paragraph", "t": "§ 2º Os prazos internos necessários à instrução da reclamação deverão ser definidos de modo a assegurar o cumprimento do prazo previsto no § 1º."}, {"c": "dou-paragraph", "t": "CAPÍTULO IX"}, {"c": "dou-paragraph", "t": "DAS RESPONSABILIDADES"}, {"c": "dou-paragraph", "t": "Art. 43. Os integrantes da Rede SIC/MAPA deverão observar as disposições da Lei nº 12.527, de 18 de novembro de 2011, do Decreto nº 7.724, de 16 de maio de 2012, e das demais normas aplicáveis ao acesso à informação, sujeitando-se à responsabilização pelas condutas ilícitas previstas na legislação."}, {"c": "dou-paragraph", "t": "Parágrafo único. O disposto no caput e nos arts. 44 a 46 aplica-se igualmente aos agentes públicos, empregados públicos, colaboradores e demais pessoas que, em razão de vínculo ou do exercício de atribuições junto ao Ministério da Agricultura e Pecuária, tenham acesso, guarda ou conhecimento de informações sob custódia do órgão."}, {"c": "dou-paragraph", "t": "Art. 44. Constituem condutas passíveis de responsabilização aquelas previstas no art. 32 da Lei nº 12.527, de 18 de novembro de 2011, e no art. 65 do Decreto nº 7.724, de 16 de maio de 2012, sem prejuízo das demais hipóteses de responsabilização previstas na legislação aplicável."}, {"c": "dou-paragraph", "t": "Art. 45. No caso de extravio da informação objeto de pedido de acesso, poderá o interessado requerer à autoridade competente a imediata abertura de sindicância destinada à apuração do desaparecimento da respectiva documentação, nos termos do art. 7º da Lei nº 12.527, de 18 de novembro de 2011."}, {"c": "dou-paragraph", "t": "Art. 46. A pessoa natural ou entidade privada que detenha informações em virtude de vínculo de qualquer natureza com o Ministério da Agricultura e Pecuária deverá observar as disposições aplicáveis ao acesso à informação e sujeitar-se-á às sanções previstas na legislação em caso de descumprimento."}, {"c": "dou-paragraph", "t": "§ 1º Quando a informação objeto do pedido estiver sob a guarda de pessoa natural ou entidade privada de que trata o caput, caberá à unidade competente do Ministério da Agricultura e Pecuária adotar as providências necessárias para sua obtenção, permanecendo o Ministério responsável pelo atendimento do pedido de acesso à informação."}, {"c": "dou-paragraph", "t": "§ 2º As sanções aplicáveis às pessoas naturais e às entidades privadas observarão o disposto no art. 66 do Decreto nº 7.724, de 16 de maio de 2012, e demais normas pertinentes."}, {"c": "dou-paragraph", "t": "CAPÍTULO X"}, {"c": "dou-paragraph", "t": "DO MONITORAMENTO DA LEI Nº 12.527, DE 18 DE NOVEMBRO DE 2011"}, {"c": "dou-paragraph", "t": "Art. 47. O monitoramento da aplicação da Lei nº 12.527, de 18 de novembro de 2011, compete à Autoridade de Monitoramento da Lei nº 12.527, de 18 de novembro de 2011, exercida pelo Chefe da Assessoria Especial de Controle Interno do Ministério da Agricultura e Pecuária, nos termos do art. 5º, § 1º, do Decreto nº 11.529, de 16 de maio de 2023."}, {"c": "dou-paragraph", "t": "Parágrafo único. Para o exercício das competências previstas no art. 40 da Lei nº 12.527, de 18 de novembro de 2011, e no art. 67 do Decreto nº 7.724, de 16 de maio de 2012, a Autoridade de Monitoramento acompanhará a atuação da Rede SIC/MAPA, com a finalidade de avaliar o cumprimento da Lei nº 12.527, de 18 de novembro de 2011, no âmbito do Ministério, podendo solicitar informações, indicadores e outros elementos necessários ao desempenho de suas atribuições."}, {"c": "dou-paragraph", "t": "Art. 48. No exercício das atividades de monitoramento da Rede SIC/MAPA, compete à Autoridade de Monitoramento:"}, {"c": "dou-paragraph", "t": "I - assegurar o cumprimento das normas relativas ao acesso à informação, de forma eficiente e adequada aos objetivos da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "II - elaborar relatório anual com informações referentes à implementação da Lei nº 12.527, de 18 de novembro de 2011, no âmbito do Ministério, que será encaminhado ao Ministro de Estado da Agricultura e Pecuária, conforme disposto no art. 67, caput, inciso II, do Decreto nº 7.724, de 16 de maio de 2012;"}, {"c": "dou-paragraph", "t": "III - recomendar as medidas indispensáveis à implementação e ao aperfeiçoamento das normas e dos procedimentos necessários ao correto cumprimento do disposto na Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "IV - orientar as unidades do Ministério da Agricultura e Pecuária quanto ao cumprimento das disposições da Lei nº 12.527, de 18 de novembro de 2011, e de seus regulamentos;"}, {"c": "dou-paragraph", "t": "V - manifestar-se sobre as reclamações apresentadas em razão de omissão de resposta a pedidos de acesso à informação, observadas as disposições da legislação aplicável;"}, {"c": "dou-paragraph", "t": "VI - encaminhar à Corregedoria do Ministério da Agricultura e Pecuária os casos de descumprimento da Lei nº 12.527, de 18 de novembro de 2011, para apuração de eventual infração administrativa, conforme previsto no art. 32 da Lei nº 12.527, de 18 de novembro de 2011;"}, {"c": "dou-paragraph", "t": "VII - avaliar e monitorar a implementação da transparência ativa e passiva no âmbito do Ministério, bem como recomendar medidas destinadas ao seu aperfeiçoamento;"}, {"c": "dou-paragraph", "t": "VIII - solicitar informações e esclarecimentos às unidades integrantes da Rede SIC/MAPA sempre que necessários ao exercício de suas atribuições; e"}, {"c": "dou-paragraph", "t": "IX - subsidiar o Ministro de Estado da Agricultura e Pecuária na apreciação dos recursos em segunda instância interpostos com fundamento na Lei nº 12.527, de 18 de novembro de 2011."}, {"c": "dou-paragraph", "t": "Parágrafo único. As unidades integrantes da Rede SIC/MAPA deverão prestar, tempestivamente, as informações e os esclarecimentos solicitados pela Autoridade de Monitoramento, bem como adotar as providências necessárias ao atendimento das orientações e recomendações expedidas no exercício de suas atribuições."}, {"c": "dou-paragraph", "t": "CAPÍTULO XI"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES FINAIS"}, {"c": "dou-paragraph", "t": "Art. 49. As dúvidas sobre a aplicação desta Portaria e as solicitações de esclarecimentos adicionais deverão ser dirigidas à Ouvidoria, por meio do SIC, pelos canais oficiais constantes do art. 8º."}, {"c": "dou-paragraph", "t": "Art. 50. Esta Portaria será revisada periodicamente para garantir sua atualização e eficácia, levando em consideração as mudanças na legislação, as necessidades identificadas e as práticas recomendadas no campo do acesso à informação e da transparência pública."}, {"c": "dou-paragraph", "t": "Art. 51. Fica revogada a Portaria MAPA nº 147, de 23 de abril de 2020."}, {"c": "dou-paragraph", "t": "Art. 52. Esta Portaria entra em vigor trinta dias após a data de sua publicação."}, {"c": "assina", "t": "CLEBER OLIVEIRA SOARES"}, {"c": "anexo", "t": "ANEXOTERMO DE RESPONSABILIDADE PARA ACESSO À INFORMAÇÃO PESSOAL POR TERCEIROS"}, {"c": "dou-paragraph", "t": "Nos termos do disposto na Lei nº 12.527, de 18 de novembro de 2011, e de sua regulamentação, declaro que tive acesso à informação aqui descrita e que a utilizarei exclusivamente com a finalidade declarada, responsabilizando-me civil, penal e administrativamente por qualquer uso diverso ou por qualquer prejuízo à intimidade, à honra e à vida privada de seus titulares e de seus herdeiros."}, {"c": "dou-paragraph", "t": "Dados da informação:"}, {"c": "", "t": "Nome completo dos titulares da informação:"}, {"c": "", "t": "Descrição da informação:"}, {"c": "", "t": "Finalidade do acesso:"}, {"c": "", "t": "Forma do acesso:"}, {"c": "", "t": "[acesso local], [cópia]"}, {"c": "", "t": "Data do acesso:"}, {"c": "", "t": "Prazo de acesso (quando aplicável)"}, {"c": "", "t": "Entre [00:00] e [00:00] horas"}, {"c": "dou-paragraph", "t": "Dados do requerente:"}, {"c": "", "t": "Nome completo:"}, {"c": "", "t": "Endereço residencial:"}, {"c": "", "t": "Documento de identificação"}, {"c": "", "t": "[incluir a cópia do documento com foto]"}, {"c": "", "t": "Telefone:"}, {"c": "dou-paragraph", "t": "(Local), (data)"}, {"c": "dou-paragraph", "t": "_________________________________________"}, {"c": "dou-paragraph", "t": "(Assinatura do requerente)"}]});